# Stories for albums 101–150 (long format agreed with the owner: three paragraphs + a listening tip,
# ~250 words, three picks). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_101_150.py; later edits: python3 tools/apply_stories.py stories_101_150
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(101, [
'''The Electric Prunes היו חמישה צעירים מפרברי לוס אנג׳לס שניגנו במסיבות ובמוסכים, עד שהמהנדס והמפיק דייב הסינג׳ר, שעבד קודם עם הרולינג סטונס (אלבום 70), שמע אותם והחתים אותם בחברת Reprise. הוא הביא להם שיר של שתי כותבות מקצועיות, I Had Too Much to Dream (Last Night), והפך אותו לניסוי אולפן. השיר הגיע בתחילת 1967 למקום ה־11 במצעד האמריקאי, ואלבום הבכורה יצא באותה שנה.''',
'''הצליל הוא של להקת גראז׳ שנפלה לתוך מעבדה: גיטרות עם פאז ועם טרמולו רוטט, צלילים הפוכים, הדהודים ורעשים מוזרים, ומעל כל זה שירי פופ קצרים וקליטים. I Had Too Much to Dream נפתח בצליל מסתורי שמתגבר לאט, כמו חלום שהופך לסיוט, ו־Get Me to the World on Time הוא שיר קצבי ומטורף עם גיטרה שנשמעת כמו מסור. בין הניסויים יש גם שירי אהבה פשוטים, כמעט תמימים, שמזכירים שזו עדיין להקה של נערים.''',
'''הלהקה לא החזיקה מעמד: כבר באלבום השלישי המפיקים כמעט החליפו אותה בנגני אולפן. אבל ב־1972, כשהמוזיקאי והמבקר לני קיי הוציא את האוסף המפורסם Nuggets, שהחזיר לחיים את להקות הגראז׳ והפסיכדליה של שנות השישים, הוא פתח אותו דווקא ב־I Had Too Much to Dream. מאז השיר נחשב לאחד הסמלים של הרגע שבו הגראז׳ הפך לפסיכדליה, ולהקות פאנק ואינדי רבות ניגנו אותו.''',
'''שמעו את I Had Too Much to Dream ואחר כך את You're Gonna Miss Me באלבום 72: שני להיטים מאותה תקופה, אחד שנולד באולפן מקצועי בלוס אנג׳לס ואחד בטקסס הפרועה.''',
], [
('I Had Too Much to Dream (Last Night)', 'הלהיט: פתיחה מסתורית, גיטרות רוטטות וחלום שהופך לסיוט.'),
('Get Me to the World on Time', 'שיר קצבי ומטורף, עם גיטרה שנשמעת כמו מסור חשמלי.'),
('Onie', 'בלדה עדינה ותמימה, שמראה צד אחר לגמרי של הלהקה.'),
])

add(102, [
'''לורטה לין גדלה בעוני בכפר כורים קטן בהרי קנטקי, בת לכורה פחם, ונישאה כנערה צעירה מאוד. היא עברה עם בעלה למדינת וושינגטון, גידלה ארבעה ילדים, ורק בסוף שנות העשרים לחייה התחילה לשיר בפומבי, אחרי שבעלה קנה לה גיטרה זולה. ב־1960 היא הוציאה סינגל ראשון, נסעה עם בעלה ממכונית לתחנת רדיו כדי לקדם אותו, ובתוך כמה שנים הפכה לכוכבת בנאשוויל. האלבום הזה יצא ב־1967, עם המפיק אוון בראדלי.''',
'''שיר הנושא, שכתבה עם אחותה, הוא אזהרה ישירה לבעל שחוזר הביתה שיכור ומצפה לאהבה: עדיף לו שלא יבוא בכלל. זה היה משהו חדש בקאנטרי: אישה ששרה מנקודת המבט של אישה, בלי להתחנן ובלי להתייפייף, עם הומור חריף וכעס אמיתי. הקול של לין חד, צלול ובטוח, עם מבטא כפרי כבד, והליווי הוא קאנטרי נאשווילי קלאסי: גיטרת סטיל, פסנתר, כינור. לצד השירים שלה יש גם גרסאות ללהיטים של אחרים.''',
'''שיר הנושא היה הלהיט הראשון שלה שהגיע למקום הראשון במצעד הקאנטרי, ולפי המקובל האלבום היה הראשון של זמרת קאנטרי שמכר מספיק כדי לקבל תקליט זהב. לין המשיכה לכתוב שירים נועזים על חיי נשים, על נישואים, על מלחמה ועל אמצעי מניעה, שחלק מתחנות הרדיו סירבו להשמיע. היא הפכה לאחת הזמרות החשובות בתולדות הקאנטרי, וסיפור חייה הפך לסרט "בת הכורה".''',
'''שמעו את שיר הנושא ואחריו את מרל הגארד באלבום 99, מאותה שנה: שניהם כותבים על שתייה ועל חיים קשים, אבל מצדדים הפוכים של אותו שולחן מטבח.''',
], [
("Don't Come Home a Drinkin' (With Lovin' on Your Mind)", 'שיר הנושא: אזהרה חריפה ומצחיקה לבעל שיכור. הלהיט הראשון שלה במקום הראשון.'),
('There Goes My Everything', 'גרסה שלה ללהיט קאנטרי גדול של אותה שנה, על אהבה שהלכה ולא תחזור.'),
('The Shoe Goes on the Other Foot Tonight', 'שיר על היפוך תפקידים בזוגיות, עם הומור וחוצפה.'),
])

add(103, [
'''בשנות השישים המוזיקה הקלאסית של צפון הודו הייתה בעיקר עניין של אמנים בודדים, שמנגנים ראגה אחת ארוכה במשך שעה. שלושה מוזיקאים צעירים החליטו לנסות משהו אחר: שיבקומאר שארמה, שהפך את הסנטור, כלי מיתרים עממי מקשמיר שמכים בו בפטישים קטנים, לכלי קלאסי; הריפראסאד צ׳אוראסיה, נגן חליל במבוק; ובריג׳ בושאן קברה, מהראשונים שניגנו מוזיקה הודית קלאסית בגיטרה, בסגנון גיטרת סלייד. יחד הם הקליטו את Call of the Valley, שיצא בחברת His Master’s Voice בהודו.''',
'''האלבום בנוי כסוויטה שמספרת יום אחד בחייו של רועה צאן בעמק בקשמיר, מהבוקר ועד הלילה. כל חלק מבוסס על ראגה שמתאימה לשעה אחרת של היום, כמו שנהוג במוזיקה ההודית: ראגות שקטות ורעננות לבוקר, ערניות לצהריים ורכות ועמוקות לערב. הסנטור נשמע כמו טיפות מים על אבנים, החליל כמו רוח בין העצים, והגיטרה מחליקה בין הצלילים כמו קול אנושי. ברקע מלווה הטבלה בעדינות.''',
'''אף שהוא מבוסס על מוזיקה קלאסית ישנה מאוד, האלבום קצר ונגיש, ולכן הפך לדלת כניסה למאזינים שלא הכירו את המוזיקה ההודית. הוא נחשב לאחד מתקליטי המוזיקה ההודית הנמכרים ביותר בעולם, ושלושת הנגנים הפכו לכוכבים גדולים. שארמה וצ׳אוראסיה המשיכו לנגן יחד עוד עשרות שנים, וגם לכתוב פסקולים לסרטי בוליווד.''',
'''הקשיבו מההתחלה ועד הסוף, כמו ליום אחד שעובר, ואם אפשר, התחילו בבוקר. ואחר כך השוו לראווי שנקר באלבום 111: ראגה ארוכה אחת לעומת יום שלם בחצי שעה.''',
], [
('Ahir-Bhairav', 'הבוקר בעמק: ראגה רגועה ורעננה, והסנטור נשמע כמו מים זורמים.'),
('Piloo – Teen Tala', 'חלק רך ומלנכולי, עם דו־שיח יפה בין החליל לגיטרה.'),
('Bhoop – Jhap Tala', 'ראגה שמחה ופשוטה, שבה שלושת הכלים משתלבים זה בזה.'),
])

add(104, [
'''אחרי אלבום הבכורה (אלבום 91), הוולווט אנדרגראונד נפרדו מאנדי וורהול ומניקו, והחליטו להיות רועשים יותר מכל מה שעשו קודם. בספטמבר 1967 הם נכנסו לאולפן בניו יורק עם המפיק טום וילסון, והקליטו את White Light/White Heat בכמה ימים בלבד, כמעט הכול בטייק אחד, בעוצמה של הופעה. לו ריד וג׳ון קייל כבר התחילו לריב, וזה נשמע. האלבום יצא בינואר 1968, והיה האחרון של קייל בלהקה.''',
'''זה אחד האלבומים הרועשים והמרעישים שהוקלטו עד אז: גיטרות מעוותות, עוגב צורם, ויולה חשמלית, ותופים של מורין טאקר שממשיכים בלי לעצור. ב־The Gift קייל מקריא, בקול יבש ומבטא וולשי, סיפור קצר ומבהיל של ריד, בערוץ אחד של הסטריאו, ובערוץ השני הלהקה מנגנת. ו־Sister Ray, בסוף, הוא ג׳אם של כמעט שבע־עשרה דקות, שהוקלט בטייק אחד. לפי הסיפור, מהנדס ההקלטה פשוט יצא מהחדר באמצע והשאיר אותם לנגן.''',
'''האלבום נכשל כמעט לגמרי: הוא נכנס רק לתחתית המצעד האמריקאי, ותחנות הרדיו לא התקרבו אליו. אבל כמו האלבום הראשון, גם הוא הפך לתנ״ך של מוזיקאים: הנויז, הפאנק, להקות הרוק האלטרנטיבי של שנות השמונים והתשעים, כולם למדו ממנו שרעש יכול להיות יפה ומפחיד בו בזמן. הוא מראה צד קיצוני ופרוע של 1967, רחוק מאוד מ"קיץ האהבה".''',
'''שמעו את The Gift עם אוזניות, ונסו להקשיב פעם רק לסיפור ופעם רק למוזיקה. ואם יש לכם אומץ, הקדישו ל־Sister Ray שבע־עשרה דקות בלי הפרעה.''',
], [
('White Light/White Heat', 'הפתיחה: רוקנרול מהיר ורועש, עם פסנתר שמכה ומקהלה צועקת.'),
('The Gift', 'סיפור קצר ומבהיל, בקולו של ג׳ון קייל, מעל גיטרות רועשות.'),
('Sister Ray', 'ג׳אם אדיר של כמעט שבע־עשרה דקות, שהוקלט בטייק אחד.'),
])

add(105, [
'''פחות משבעה חודשים אחרי Are You Experienced (אלבום 100), ג׳ימי הנדריקס כבר היה כוכב ענק, וחברת התקליטים רצתה אלבום נוסף עד סוף 1967. הוא נכנס לאולפן בלונדון עם נואל רדינג ומיץ׳ מיצ׳ל, והפעם לקח את הזמן להתנסות. בסוף העבודה התברר שהנדריקס שכח את סרטי המאסטר של צד אחד בתוך מונית בלונדון, והמפיק והמהנדס נאלצו לערבב את הצד מחדש בלילה אחד. Axis: Bold as Love יצא בדצמבר 1967 בבריטניה.''',
'''אם האלבום הראשון היה פיצוץ, זה אלבום רך ומגוון יותר, עם יותר צבעים ויותר נשמה. Little Wing הוא בלדה קצרה ויפהפייה, פחות משתי דקות וחצי, על מלאך שמרחף מעל, בהשראת מוזיקת סול. Castles Made of Sand מספר סיפורים קטנים ועצובים, If 6 Was 9 הוא הצהרה של חופש ואינדיבידואליזם, ו־Bold as Love, בסוף, בונה לאט לאחד הסולואים היפים שלו. הנדריקס ניסה כאן אפקטים חדשים וצלילים שעוברים מרמקול לרמקול.''',
'''האלבום הגיע לעשירייה הראשונה בבריטניה ובארצות הברית, והוא נחשב לאלבום שבו הנדריקס הראה שהוא לא רק גיטריסט מבריק, אלא גם כותב שירים רגיש ומלחין. Little Wing הפך לאחד השירים המוקלטים ביותר שלו, בגרסאות של אריק קלפטון, סטיבי ריי ווהן ורבים אחרים. גם העטיפה, שמציגה את הלהקה בסגנון של ציור הינדי, הפכה לסמל של התקופה.''',
'''שמעו את Little Wing ואז את The Wind Cries Mary באלבום 100: שתי בלדות, והשנייה כבר יודעת לאן היא הולכת. ושימו לב כמה קצר Little Wing: הנדריקס אומר הכול בפחות משתי דקות וחצי.''',
], [
('Little Wing', 'בלדה קצרה ויפהפייה על מלאך, עם אחד מקטעי הגיטרה העדינים ביותר ברוק.'),
('Castles Made of Sand', 'סיפורים קטנים ועצובים על חלומות שמתפרקים, עם גיטרה הפוכה.'),
('Bold as Love', 'הסיום, שמטפס לאט לאחד הסולואים היפים של הנדריקס.'),
])

add(106, [
'''ארית׳ה פרנקלין הייתה בתו של מטיף מפורסם מדטרויט, וגדלה על גוספל בכנסייה של אביה. במשך שש שנים היא הקליטה לחברת Columbia, שניסתה להפוך אותה לזמרת ג׳אז ופופ מלוטשת, בלי הצלחה גדולה. ב־1967 היא עברה ל־Atlantic, והמפיק ג׳רי וקסלר לקח אותה לאולפן קטן במאסל שולס שבאלבמה, עם נגנים מקומיים, כמעט כולם לבנים. בתוך כמה שעות הם הקליטו את I Never Loved a Man. אחר כך פרצה קטטה בין בעלה של ארית׳ה לבין אחד הנגנים, והעבודה עברה לניו יורק.''',
'''מההתחלה ברור שזה משהו אחר: ארית׳ה יושבת ליד הפסנתר ומנגנת בעצמה, והקול שלה, שעבר מהכנסייה לאולפן, עוצמתי, חם ונשלט לגמרי. הלהקה מאחוריה מנגנת פשוט ועמוק, ונותנת לה מקום. Respect, השיר של אוטיס רדינג (אלבום 51), הופך אצלה לשיר אחר לגמרי: ארית׳ה הוסיפה את ה"R-E-S-P-E-C-T" המאוית ואת הקריאות של אחיותיה ברקע, והפכה תחינה של גבר לדרישה של אישה. Do Right Woman, Do Right Man הוא בלדה איטית ועמוקה על כבוד בזוגיות.''',
'''Respect הגיע למקום הראשון במצעד האמריקאי בקיץ 1967, והפך להמנון של התנועה לזכויות האזרח ושל התנועה הפמיניסטית גם יחד. האלבום הפך את ארית׳ה ל"מלכת הסול", תואר שנשאר איתה עד מותה. הוא מראה את הרגע שבו הגוספל, הבלוז והסול התחברו בקול אחד, ורבים רואים בו את אחד מאלבומי הסול הגדולים שהוקלטו אי פעם.''',
'''שמעו את Respect כאן ואז את המקור של אוטיס רדינג באלבום 51. אותו שיר, אבל מי מבקש, ממי, ובאיזה טון? ואחר כך המשיכו לאלבום 117, שבו ארית׳ה ממשיכה עוד צעד.''',
], [
('Respect', 'השיר של אוטיס רדינג, שארית׳ה הפכה להמנון, עם ה"R-E-S-P-E-C-T" המפורסם.'),
('I Never Loved a Man (The Way I Love You)', 'השיר שהוקלט במאסל שולס: בלוז איטי שבו הכול משתנה.'),
('Do Right Woman, Do Right Man', 'בלדה עמוקה על כבוד ואהבה, עם פסנתר ועוגב של כנסייה.'),
])

add(107, [
'''ב־1967 הרולינג סטונס ניסו ללכת בעקבות הביטלס עם אלבום פסיכדלי, וזה לא עבד. בנוסף, חלק מהם נעצרו על החזקת סמים, ובריאן ג׳ונס, מייסד הלהקה (אלבום 46), התדרדר והתרחק. ב־1968, עם המפיק החדש ג׳ימי מילר, הם חזרו לשורשים: בלוז, קאנטרי ורוקנרול. Beggars Banquet יצא בדצמבר 1968, אחרי עיכוב של חודשים, כי חברת התקליטים סירבה לעטיפה המקורית, שהציגה קיר של שירותים ציבוריים עם כתובות.''',
'''האלבום נפתח ב־Sympathy for the Devil, שבו ג׳אגר שר בגוף ראשון בשם השטן, שמתהדר בכל אסונות ההיסטוריה, על קצב סמבה של תופי קונגה וקריאות "וו־וו" של מקהלה. Street Fighting Man נכתב בשנה של הפגנות ומהומות בכל העולם, ובכל זאת נשמע בעיקר כמו גיטרות אקוסטיות מחושמלות. No Expectations הוא בלוז אקוסטי עצוב, עם גיטרת סלייד של בריאן ג׳ונס, אחת התרומות האחרונות שלו ללהקה. ובסוף Salt of the Earth, שיר לכבוד "האנשים הפשוטים".''',
'''Beggars Banquet פתח את התקופה הגדולה של הסטונס: ארבעה אלבומים ברצף שרבים מחשיבים לטובים בתולדות הרוק. בריאן ג׳ונס עזב את הלהקה חצי שנה אחר כך, ומת ביולי 1969, בגיל 27. במקומו הגיע מיק טיילור, והלהקה המשיכה, קשה ובטוחה, אל Let It Bleed (אלבום 148). האלבום הראה שבשנה של ניסויים פסיכדליים, גם החזרה לשורשים יכולה להיות מהפכה.''',
'''שמעו את Sympathy for the Devil והקשיבו לקונגה ולפסנתר, איך השיר נבנה מסביבם. ואחר כך השוו את No Expectations ל־Lady Jane באלבום 70: אותו בריאן ג׳ונס, שנתיים ועולם שלם אחר כך.''',
], [
('Sympathy for the Devil', 'השטן מציג את עצמו, על קצב סמבה ומקהלה של "וו־וו".'),
('No Expectations', 'בלוז אקוסטי עצוב, עם גיטרת סלייד של בריאן ג׳ונס.'),
('Street Fighting Man', 'שיר של שנת ההפגנות, עם גיטרות אקוסטיות שנשמעות כמו חשמל.'),
])

add(108, [
'''סטיב ווינווד היה ילד פלא: בגיל 15 הוא כבר שר וניגן בעוגב בלהקת Spencer Davis Group, ובגיל 18 עזב אותה. עם שלושה חברים, המתופף והכותב ג׳ים קפאלדי, נגן הנשיפה כריס ווד והגיטריסט דייב מייסון, הוא הקים את Traffic, והארבעה עברו לגור יחד בבית כפרי בודד באנגליה כדי לכתוב ולנגן בשקט. האלבום השני שלהם, שנקרא פשוט בשם הלהקה, יצא באוקטובר 1968, אחרי שמייסון עזב, חזר ועמד לעזוב שוב.''',
'''זה אלבום שמחבר הכול: רוק, סול, פולק, ג׳אז ופסיכדליה, בנינוחות של חברים שמנגנים בחדר. הקול של ווינווד, שנשמע כמו זמר סול שחור מבוגר, מוביל את השירים שכתב עם קפאלדי, כמו Pearly Queen ו־Forty Thousand Headmen, עם חליל וסקסופון של ווד. מייסון תורם שירים פשוטים וקליטים יותר, והמפורסם מהם הוא Feelin’ Alright?, שיר על אדם שמעמיד פנים שהכול בסדר אחרי פרידה.''',
'''האלבום מראה את הרגע שבו רוקנרול בריטי התחיל להתנהג כמו ג׳אז: פחות להיטים, יותר נגינה חופשית ושיתוף. Feelin’ Alright? לא הפך ללהיט אצלם, אבל ג׳ו קוקר הקליט אותו כמה חודשים אחר כך, ומאז הוא הוקלט עשרות פעמים. Traffic המשיכו בהרכבים שונים עוד כמה שנים, וווינווד הפך לאחד הקולות החשובים של הרוק הבריטי, עד להיטי הסולו שלו בשנות השמונים.''',
'''שמעו את Feelin’ Alright? כאן, ואחר כך חפשו את הגרסה של ג׳ו קוקר. ואז חזרו לשירים של ווינווד, ושימו לב לחליל של כריס ווד, שנותן לאלבום את הצבע הכפרי שלו.''',
], [
("Feelin' Alright?", 'שיר של דייב מייסון על אדם שמעמיד פנים שהכול בסדר. הפך לקלאסיקה אצל אחרים.'),
('Pearly Queen', 'רוק קצבי ושמנמן, עם הקול הנשמתי של ווינווד.'),
('Forty Thousand Headmen', 'שיר מסתורי כמו אגדה, עם חליל שמוביל אותו.'),
])

add(109, [
'''רובין וויליאמסון ומייק הרון היו שני צעירים מאדינבורו שהסתובבו בסצנת הפולק הסקוטית, ניגנו בכל כלי שנפל לידיהם, וחלמו על מוזיקה שתחבר את הפולק הבריטי עם מוזיקה מכל העולם. הם קראו לעצמם The Incredible String Band, והמפיק ג׳ו בויד החתים אותם בחברת Elektra. The Hangman’s Beautiful Daughter, האלבום השלישי שלהם, יצא במרץ 1968, עם חברתם ליקוריס מקצ׳ני ועם כמה אורחים.''',
'''זה אלבום שלא דומה לשום דבר אחר. יש כאן סיטאר, עוד, צ׳מבלו, חלילים, כינור, גונג ועוד כלים שקשה לזהות, ושירים ארוכים שמתפתלים ומשנים כיוון בלי אזהרה. המילים מלאות ביצורי יער, בקסמים, באלוהות, בתאים ביולוגיים ובחלומות, והקולות של וויליאמסון והרון רועדים, מתרוממים ולפעמים כמעט מזייפים, ובכל זאת נשמעים כנים לגמרי. A Very Cellular Song, של יותר משלוש־עשרה דקות, עובר משיר ילדים לפזמון בהאמי ישן על אור ואהבה.''',
'''האלבום הגיע לעשירייה הראשונה בבריטניה, הצלחה מפתיעה לתקליט כל כך מוזר, והלהקה הופיעה אפילו בפסטיבל וודסטוק. מוזיקאים רבים ציינו את הלהקה כהשראה, מלד זפלין ועד להקות אינדי ופריק פולק בשנות האלפיים. זה אחד האלבומים שמראים עד כמה רחוק הלך הפולק הבריטי בסוף שנות השישים, הרבה אחרי הגיטרה והקול של ברט ג׳אנש (אלבום 56).''',
'''תנו לאלבום זמן: הוא מוזר בשמיעה הראשונה ומקסים בשלישית. התחילו מ־Koeeoaddi There, שיר על ילדות, ורק אחר כך עברו ל־A Very Cellular Song.''',
], [
('A Very Cellular Song', 'יצירה ארוכה ומתפתלת שעוברת בין עולמות, עד פזמון בהאמי ישן על אור ואהבה.'),
('Koeeoaddi There', 'שיר קסום על ילדות וזיכרונות, עם כלים מכל העולם.'),
('The Minotaur’s Song', 'שיר מצחיק בסגנון אופרטה, מפי המינוטאור מהמיתולוגיה.'),
])

add(110, [
'''ב־1968 ריי דייוויס, מנהיג הקינקס (אלבומים 66 ו־97), כבר לא ניסה בכלל להתאים לאופנה. בזמן שכולם דיברו על מהפכה, הוא כתב אלבום שלם על געגוע: לכפר האנגלי, לתה, לבירה מהחבית, לחברים מהילדות ולתמונות ישנות. The Kinks Are the Village Green Preservation Society יצא ב־22 בנובמבר 1968, באותו יום שבו יצא גם "האלבום הלבן" של הביטלס. הקינקס עדיין לא יכלו להופיע באמריקה, והאלבום כמעט לא נשמע שם.''',
'''שיר הנושא הוא מעין מניפסט מצחיק: "אגודה לשימור כר הדשא של הכפר", שמגינה על דונלד דאק, על עוגות קרם ועל כל מה שישן וטוב. משם האלבום עובר בין דמויות וזיכרונות: Do You Remember Walter? הוא על חבר ילדות שכבר לא דומה למה שהיה, Picture Book על אלבום תמונות משפחתי, ו־Village Green על מי שחוזר לכפר ומגלה שהוא השתנה. המוזיקה פשוטה ויפה, עם צ׳מבלו, פסנתר והרמוניות רכות, בין פופ למוזיקת אולמות ישנה.''',
'''בזמנו האלבום נכשל כמעט לגמרי, והיה הראשון של הלהקה שלא נכנס למצעד הבריטי. אבל עם השנים הוא הפך לאחד האלבומים האהובים של שנות השישים, ורבים רואים בו את יצירת המופת של הקינקס. להקות בריטיות רבות, מהג׳אם ועד בלר, הלכו בעקבות הדרך של דייוויס: לכתוב על החיים הקטנים של אנגליה בחמלה ובעוקץ.''',
'''שמעו את Do You Remember Walter? ואז חשבו על חבר ילדות משלכם. ואחר כך השוו ל־Waterloo Sunset באלבום 97: אותו כותב, שנה אחת קודם, מסתכל על העיר במקום על הכפר.''',
], [
('The Village Green Preservation Society', 'שיר הנושא: מניפסט מצחיק לשימור כל מה שישן וטוב.'),
('Do You Remember Walter?', 'שיר על חבר ילדות שהזמן שינה, ועל הזיכרונות שנשארים.'),
('Picture Book', 'שיר עליז על אלבום תמונות משפחתי, עם פזמון שנתקע בראש.'),
])

add(111, [
'''ראווי שנקר נולד ב־1920 בבנארס שבהודו, ובילה את נעוריו כרקדן בלהקת המחול של אחיו הגדול, שסיירה באירופה ובאמריקה. בגיל 18 עזב הכול כדי ללמוד סיטאר אצל מורה גדול, שבע שנים של לימוד קשה ובודד. בשנות החמישים הוא כבר היה כוכב בהודו, והתחיל להופיע במערב, מול קהל שלא ידע דבר על המוזיקה הזאת. The Sounds of India, שהוקלט ב־1957 באולפן בניו יורק, נבנה בדיוק בשביל הקהל הזה.''',
'''האלבום נפתח בהסבר: שנקר עצמו מדבר אל המאזין, באנגלית ברורה ובחיוך, ומסביר מה זו ראגה, מה זה טאלה, מחזור הקצב, ואיך נבנית הופעה. אחרי כל הסבר הוא מדגים על הסיטאר. ואז מגיעים הקטעים עצמם: הסיטאר מתחיל לאט, בלי קצב, בוחן כל צליל בראגה כמו מי שנכנס לחדר חשוך, ואז נכנסת הטבלה של צ׳אטור לאל, והשניים מאיצים יחד, משוחחים ומתחרים, עד שיא מסחרר. הטאנפורה מזמזמת ברקע כל הזמן, כמו אוויר.''',
'''זה היה אחד התקליטים הראשונים שהביאו את המוזיקה ההודית לבתים במערב, והוא פתח את הדלת לכל מה שבא אחריו. בשנות השישים ג׳ורג׳ הריסון מהביטלס למד סיטאר אצל שנקר, והסיטאר נכנס לרוק (אלבומים 55 ו־70). שנקר הופיע בפסטיבל מונטריי ובפסטיבל וודסטוק, והפך לשגריר של המוזיקה ההודית בעולם. הוא המשיך להופיע עד גיל 92, ושתי בנותיו, אנושקה שנקר ונורה ג׳ונס, הפכו גם הן למוזיקאיות.''',
'''אל תדלגו על ההסבר בהתחלה: הוא הופך את כל השאר לברור. ואחר כך השוו ל־Call of the Valley באלבום 103: ראגה ארוכה אחת מול סוויטה של יום שלם.''',
], [
('An Introduction to Indian Music', 'שנקר מסביר בעצמו, באנגלית ובדוגמאות, איך מקשיבים למוזיקה הזאת.'),
('Bhimpalasi', 'ראגה של אחר הצהריים: פתיחה איטית ושקטה שמתעוררת לאט ומאיצה.'),
('Dadra', 'קטע קליל וקצבי, שבו הסיטאר והטבלה משוחחים בשמחה.'),
])

add(112, [
'''בסוף שנות השישים ברזיל הייתה תחת דיקטטורה צבאית, וקבוצה של מוזיקאים צעירים, ביניהם קאטאנו ולוזו (אלבום 129) וז׳ילברטו ז׳יל, יצאה לתנועה שכונתה "טרופיקליה": ערבוב פרוע של מוזיקה ברזילאית עם רוק פסיכדלי, אוונגרד וסאטירה. הלהקה הצעירה ביותר והמשוגעת ביותר בתנועה הייתה Os Mutantes, "המוטנטים": שני האחים ארנלדו באפטיסטה וסרג׳יו דיאס, וחברתם ריטה לי, מסאו פאולו, שלושתם בני עשרים או פחות. אלבום הבכורה שלהם יצא ביוני 1968, עם המעבד רוז׳ריו דופראט.''',
'''זה אלבום שמשחק בכל: סמבה ובוסה נובה לצד גיטרות מעוותות, פידבק, רעשים, תזמורת, צלצולי פעמונים ואפילו קולות של אכילה. Panis et Circenses, שכתבו להם קאטאנו וז׳יל, מתחיל כמו שיר חגיגי של מלכים ומתפרק באמצע לצלילים של ארוחת משפחה משעממת. A Minha Menina, של ז׳ורז׳י בן, הוא שיר שמח עם גיטרה מלוכלכת, ו־Baby הוא בלדה עדינה ומצחיקה. יש גם גרסה צרפתית לשיר של פרנסואז הארדי, וגרסה פורטוגזית לשיר של The Mamas & the Papas (אלבום 67).''',
'''האלבום מכר מעט מאוד בזמנו, והלהקה התפרקה בשנות השבעים. אבל בשנות התשעים מוזיקאים אמריקאים ובריטים גילו אותה מחדש: קורט קוביין מנירוונה סיפר כמה אהב אותם, ודייוויד ביירן הוציא אוסף שלהם. היום Os Mutantes נחשבים לאחת הלהקות המקוריות של שנות השישים, והוכחה שהרוק הפסיכדלי לא היה רק אמריקאי ובריטי.''',
'''שמעו את Panis et Circenses עד הסוף, ואל תיבהלו כשהשיר עוצר באמצע. ואחר כך עברו לאלבום 129, של קאטאנו ולוזו, מאותה שנה ומאותה תנועה.''',
], [
('Panis et Circenses', 'שיר חגיגי שמתפרק באמצע לארוחה משפחתית משעממת. ההמנון של הטרופיקליה.'),
('A Minha Menina', 'שיר שמח ומלוכלך של ז׳ורז׳י בן, עם גיטרת פאז ומחיאות כפיים.'),
('Baby', 'בלדה עדינה ואירונית, שבה ריטה לי שרה על הדברים שחייבים להכיר.'),
])

add(113, [
'''ב־1968 ג׳ימי הנדריקס היה אחד האמנים הגדולים בעולם, ועבר לגור בניו יורק. את האלבום השלישי, הכפול, הוא הפיק בעצמו, באולפן חדש בעיר, במשך חודשים, עם אינספור טייקים ועם חברים שהגיעו לנגן איתו: סטיב ווינווד (אלבום 108) על העוגב, אל קופר, המתופף באדי מיילס ורבים אחרים. המפיק צ׳אס צ׳נדלר, שגילה אותו (אלבום 100), פרש באמצע, מתוסכל מהזמן ומהמסיבות באולפן. Electric Ladyland יצא באוקטובר 1968.''',
'''זה אלבום ענק ומגוון: בלוז, פאנק, פסיכדליה, ג׳אז, מדע בדיוני. Voodoo Chile הוא ג׳אם בלוז של רבע שעה, שהוקלט בלילה אחד עם ווינווד, ו־Voodoo Child (Slight Return), בסוף, הוא אחד הקטעים הכבדים והמפורסמים שלו. 1983... (A Merman I Should Turn to Be) הוא מסע של כמעט רבע שעה אל מתחת לים, וכמעט לא מבוסס על שיר רגיל. ו־All Along the Watchtower, שיר של בוב דילן, הופך אצלו לסערה של גיטרות. דילן עצמו אהב את הגרסה כל כך, שמאז הוא מנגן את השיר כמו הנדריקס.''',
'''זה היה האלבום היחיד של הנדריקס שהגיע למקום הראשון באמריקה, והאחרון שהוציא עם ה־Experience. רבים רואים בו את השיא שלו: אמן שמשתמש באולפן כמו בכלי נגינה, ולוקח את הבלוז לחלל. פחות משנתיים אחר כך הנדריקס מת, בגיל 27. All Along the Watchtower הפך לאחת הגרסאות המפורסמות של שיר של דילן, ואולי המפורסמת שבהן.''',
'''שמעו את All Along the Watchtower, ואחר כך את המקור השקט של דילן, מאלבום שיצא כמה חודשים קודם. ואם יש לכם רבע שעה, הקדישו אותה ל־Voodoo Chile, כמו בלילה במועדון.''',
], [
('All Along the Watchtower', 'השיר של דילן, בגרסה שהפכה לסערה של גיטרות.'),
('Voodoo Child (Slight Return)', 'הסיום: ריף כבד ומפורסם, וגיטרה שמדברת, צועקת ובוכה.'),
('Voodoo Chile', 'ג׳אם בלוז של רבע שעה, שהוקלט בלילה אחד עם סטיב ווינווד.'),
])

add(114, [
'''ליאונרד כהן גדל במונטריאול במשפחה יהודית מבוססת, והיה משורר וסופר מוערך בקנדה, שכתב ספרי שירה ושני רומנים. באמצע שנות השישים, כשהבין שמשירה קשה להתפרנס, החליט לנסות את כוחו בכתיבת שירים לזמרים. הזמרת ג׳ודי קולינס הקליטה את Suzanne, השיר הפך למוכר, והמפיק ג׳ון המונד, שהחתים גם את בוב דילן (אלבום 36), החתים אותו בחברת Columbia. אלבום הבכורה יצא בסוף 1967, כשכהן היה בן 33, מבוגר בהרבה מרוב הזמרים של אותה תקופה.''',
'''הקול של כהן נמוך, שקט ומונוטוני, כמעט מדבר, והגיטרה שלו מנגנת תבניות פשוטות וחוזרות, בהשפעת מוזיקה ספרדית. אבל המילים הן מה שחשוב: שירה אמיתית, על אהבה, על אמונה, על פרידה ועל גוף, עם דימויים שנשארים בזיכרון. Suzanne הוא על אישה שמגישה תה ותפוזים ליד הנהר, So Long, Marianne הוא פרידה ממריאן, האהבה שלו מהאי היווני הידרה, ו־Hey, That’s No Way to Say Goodbye הוא שיר פרידה עדין. המפיק הוסיף מיתרים וקולות נשיים, וכהן לא אהב את התוספות.''',
'''בזמנו האלבום לא מכר הרבה באמריקה, אבל בבריטניה ובאירופה הוא הצליח, ובמשך השנים הוא הפך לאחד מאלבומי הבכורה החשובים של כותב שירים. כהן המשיך לכתוב ולהקליט עוד חמישים שנה, עד מותו ב־2016, והפך לאחד הכותבים הנערצים בעולם. גם בישראל הוא אהוב מאוד, והופיע כאן כמה פעמים, כולל מול חיילים בסיני במלחמת יום הכיפורים.''',
'''הקשיבו למילים, ואם צריך, קראו אותן מול העיניים. והשוו לבוב דילן באלבום 36: שני כותבים ששרים בקול לא מלוטש, אחד צעיר ומהיר ואחד מבוגר ואיטי.''',
], [
('Suzanne', 'השיר המפורסם שלו: אישה ליד הנהר, תה ותפוזים, ואהבה שלא מתממשת.'),
('So Long, Marianne', 'פרידה חמה ועצובה מאהבה גדולה, עם פזמון שקל לשיר יחד.'),
('Hey, That’s No Way to Say Goodbye', 'שיר פרידה עדין, שמנסה להיפרד יפה.'),
])

add(115, [
'''ג׳וני קאש היה אחד מכוכבי הקאנטרי הגדולים של שנות החמישים, אבל ב־1967 הקריירה שלו הייתה בשפל: התמכרות לכדורים, מעצרים קטנים, הופעות שבוטלו. בעזרת ג׳ון קרטר, שהפכה לאשתו, הוא התחיל להתאושש, והחליט להגשים חלום ישן: להקליט אלבום הופעה בבית סוהר. הוא כבר הופיע בבתי כלא שנים, ואסירים כתבו לו מכתבים בגלל השיר Folsom Prison Blues מ־1955. ב־13 בינואר 1968 הוא הופיע פעמיים בכלא פולסום בקליפורניה, והקטעים הוקלטו.''',
'''קאש עולה לבמה עם "שלום, אני ג׳וני קאש", ומשם זה רק מתחמם. הוא שר על רצח, על כלא, על עונש מוות ועל חרטה, מול אנשים שחיים את זה, והם מגיבים לכל שורה: צועקים, צוחקים ומריעים, במיוחד כשב־Folsom Prison Blues הוא שר "יריתי באדם ברינו רק כדי לראות אותו מת". הוא מתלוצץ עם הקהל, מקלל את הסוהרים, ושר גם שירים מצחיקים ודואט עם ג׳ון קרטר. באמצע הוא שר שיר שכתב אחד האסירים, Greystone Chapel, והאסיר עצמו יושב בקהל.''',
'''האלבום הגיע למקום הראשון במצעד הקאנטרי, נכנס לעשרים הראשונים במצעד הכללי, והחזיר את קאש לפסגה. שנה אחר כך הוא כבר הגיש תוכנית טלוויזיה משלו וחזר לכלא אחר, סן קוונטין (אלבום 141). קאש עצמו מעולם לא ישב בכלא, רק לילות ספורים במעצר, אבל הוא הפך לקול של מי שאין להם קול, והאלבום הזה הוא הרגע שבו זה קרה.''',
'''שמעו את Folsom Prison Blues והקשיבו לקהל בשורה על רינו. ואחר כך חזרו למרל הגארד באלבום 99: אסיר לשעבר שראה את קאש מופיע בכלא, והחליט בזכותו להיות זמר.''',
], [
('Folsom Prison Blues', 'הפתיחה, והרגע שבו הקהל של האסירים מתפוצץ בשורה המפורסמת.'),
('Greystone Chapel', 'שיר שכתב אסיר בפולסום, וקאש שר אותו מולו.'),
('Jackson', 'דואט עליז ומתגרה עם ג׳ון קרטר, על זוג שמאיים לברוח לג׳קסון.'),
])

add(116, [
'''לורה נירו גדלה בברונקס שבניו יורק, בת לאב נגן חצוצרה, והקשיבה לדו־וופ שצעירים שרו ברחוב, לסול, לג׳אז ולמחזות זמר. היא התחילה לכתוב שירים כנערה, ובגיל 19 כבר הוציאה אלבום ראשון. ההופעה שלה בפסטיבל מונטריי ב־1967 התקבלה בקרירות, אבל המפיק דייוויד גפן האמין בה והחתים אותה בחברת Columbia. Eli and the Thirteenth Confession, שיצא במרץ 1968, כשהייתה בת 20, הוא האלבום שבו היא מצאה את הקול שלה.''',
'''נירו שרה ומנגנת בפסנתר, והשירים שלה משנים קצב ומצב רוח כל כמה שניות: מגוספל סוחף לבלדה שקטה, מסול לג׳אז ולמחזמר, עם הקול שלה, שמטפס, לוחש וצועק. השירים מספרים על אהבה, על תשוקה, על עיר גדולה ועל התבגרות, והאלבום בנוי כמו סיפור של נערה שהופכת לאישה. Eli’s Comin’ הוא אזהרה דרמטית מפני גבר מסוכן, Stoned Soul Picnic הוא הזמנה חגיגית לפיקניק, ו־Sweet Blindness הוא שיר שמח ומשכר על יין ועל אהבה.''',
'''האלבום עצמו לא הפך ללהיט, אבל השירים שבו כן, בביצוע של אחרים: להקת The 5th Dimension הפכה את Stoned Soul Picnic ואת Sweet Blindness ללהיטים, ו־Three Dog Night הצליחו עם Eli’s Comin’. נירו השפיעה על דור שלם של זמרות וכותבות שירים, ורבות מהן, וגם מוזיקאים כמו אלטון ג׳ון, אמרו שלמדו ממנה איך לכתוב. היא מתה ב־1997, בגיל 49.''',
'''הקשיבו לאלבום ברצף, כמו לסיפור אחד. ואחר כך חפשו את Stoned Soul Picnic בגרסה של The 5th Dimension: אותו שיר, אבל הרבה יותר מסודר, ואולי פחות מרגש.''',
], [
('Eli’s Comin’', 'אזהרה דרמטית מפני גבר מסוכן, שמתחילה בשקט ומתפוצצת.'),
('Stoned Soul Picnic', 'הזמנה חגיגית לפיקניק, מלאה בשמחה ובריח של קיץ.'),
('Sweet Blindness', 'שיר שמח ומשכר על יין ואהבה, עם פסנתר וקולות כמו בגוספל.'),
])

add(117, [
'''בשנת 1967 ארית׳ה פרנקלין כבר הייתה "מלכת הסול" (אלבום 106), עם להיט אחרי להיט. בסוף אותה שנה היא חזרה לאולפן בניו יורק עם המפיק ג׳רי וקסלר ועם אותם נגנים ממאסל שולס, וגם עם אחיותיה וקבוצת הזמרות The Sweet Inspirations בקולות הרקע. Lady Soul יצא בינואר 1968, ורבים מחשיבים אותו לטוב מכל אלבומיה.''',
'''הקול של ארית׳ה כאן בשיא כוחו: מלא, בטוח וגמיש, מעבר קל מלחישה לצעקה. Chain of Fools, עם הגיטרה המפורסמת שמתנדנדת בפתיחה, הוא שיר על אישה שמבינה שהיא רק חוליה בשרשרת של גבר, ו־(You Make Me Feel Like) A Natural Woman, שכתבו קרול קינג וג׳רי גופין לבקשתו של וקסלר, הוא אחד משירי האהבה הגדולים של הסול. Ain’t No Way, שכתבה אחותה קרולין, הוא בלדה עמוקה שבה הקול של ארית׳ה מטפס לגבהים. באחד השירים מנגן כאורח גם אריק קלפטון.''',
'''שלושה סינגלים מהאלבום הגיעו לעשירייה הראשונה, והאלבום עצמו הגיע למקום השני במצעד האמריקאי. באותה שנה, 1968, ארית׳ה שרה בהלוויה של מרטין לותר קינג, שהיה חבר של אביה. Lady Soul הוא אולי הרגע השלם ביותר של הסול של אטלנטיק: גוספל, בלוז ופופ, והקול הגדול של התקופה.''',
'''השוו את A Natural Woman לגרסה של קרול קינג עצמה, שיצאה שלוש שנים אחר כך: הכותבת ששרה בשקט, מול הזמרת ששרה בכל הכוח. ואחר כך חזרו לאלבום 106, וחשבו כמה רחוק היא הגיעה בשנה אחת.''',
], [
('Chain of Fools', 'גיטרה מתנדנדת, קולות רקע, ואישה שמבינה שהיא רק חוליה בשרשרת.'),
('(You Make Me Feel Like) A Natural Woman', 'שיר האהבה הגדול של קרול קינג, בקול שנדמה שמכיל הכול.'),
('Ain’t No Way', 'בלדה עמוקה שכתבה אחותה, עם קולות רקע שמטפסים איתה לשמיים.'),
])

add(118, [
'''Blue Cheer היו שלישייה מסן פרנסיסקו, ששמם לקוח מזן של אל־אס־די: הבסיסט והזמר דיקי פיטרסון, הגיטריסט לי סטיבנס והמתופף פול וויילי. בזמן שהלהקות האחרות בעיר ניגנו מוזיקה רכה ומתפתלת, הם רצו פשוט להיות הכי רועשים שאפשר, עם קירות של מגברים. אחרי שראו את ג׳ימי הנדריקס בפסטיבל מונטריי, הם החליטו ללכת עוד יותר רחוק. אלבום הבכורה שלהם, Vincebus Eruptum, יצא בינואר 1968.''',
'''זה אלבום קצר, שישה שירים בלבד, וכמעט כולם בלוז ישן שמנוגן בעוצמה מטורפת: גיטרה מעוותת עם פידבק שלא נגמר, בס עבה ותופים שמכים בכל הכוח. Summertime Blues, הלהיט של אדי קוקרן מ־1958 על נער שנתקע בעבודה בקיץ, הופך אצלם לקטע פרוע ורועם. Rock Me Baby של בי. בי. קינג ו־Parchman Farm של מוס אליסון מקבלים את אותו טיפול. אין כאן עדינות ואין כאן דיוק, רק עוצמה.''',
'''Summertime Blues הגיע למקום ה־14 במצעד האמריקאי, ורבים רואים בו את הלהיט הראשון של הרוק הכבד, ובאלבום אחד מאבות ההבי מטאל, הסטונר רוק והפאנק. הלהקה החזיקה מעמד רק כמה שנים בהרכב המקורי, אבל להקות רבות, מהסטוג׳ס ועד להקות הגראנג׳ של שנות התשעים, אמרו שלמדו ממנה כמה רעש זה יותר מדי: אף פעם לא.''',
'''שמעו את Rock Me Baby כאן, ואז את אוטיס רדינג שר אותו באלבום 51: אותו בלוז, פעם בנשמה ופעם בעוצמה. ואת Summertime Blues שמעו בווליום שאתם מעזים.''',
], [
('Summertime Blues', 'הלהיט של אדי קוקרן, בגרסה רועמת שנחשבת לאחד הלהיטים הראשונים של הרוק הכבד.'),
('Rock Me Baby', 'הבלוז של בי. בי. קינג, מעוות ורועש עד הקצה.'),
('Doctor Please', 'שיר מקורי שלהם, ארוך וכבד, עם סולו גיטרה שמתפרק לרעש.'),
])

add(119, [
'''בסוף 1967 הבירדס התפרקו לאט: דייוויד קרוסבי פוטר, והמתופף עזב באמצע ההקלטות, ונשארו רק רוג׳ר מקגווין וכריס הילמן (אלבום 94). דווקא מתוך המשבר הזה, עם המפיק גארי אשר, יצא אחד האלבומים היפים של הלהקה. The Notorious Byrd Brothers יצא בינואר 1968. על העטיפה מופיעים חברי הלהקה בחלונות של אורווה ישנה, ובחלון אחד עומד סוס. אנשים טענו שהסוס מחליף את קרוסבי, והלהקה לא בדיוק הכחישה.''',
'''האלבום עובר בחן בין סגנונות, כמעט בלי הפסקות בין השירים: פולק־רוק רך, קאנטרי, פסיכדליה, ג׳אז, ואפילו צלילים של סינתיסייזר מוג, מהשימושים הראשונים בו ברוק. Goin’ Back ו־Wasn’t Born to Follow הם שני שירים של קרול קינג וג׳רי גופין, שמתאימים לבירדס כאילו נכתבו בשבילם. Draft Morning הוא שיר שקט ועצוב על צעיר שנקרא לצבא בזמן מלחמת וייטנאם, עם רעשי קרב ברקע. ו־Artificial Energy, בפתיחה, הוא שיר עם כלי נשיפה על סמים שמעוררים ואז מפילים.''',
'''בזמנו האלבום מכר פחות מקודמיו, אבל היום רבים רואים בו את הטוב שבאלבומי הבירדס. Wasn’t Born to Follow נכנס שנה אחר כך לסרט "הנוסע המהיר", ונהיה לאחד השירים שמזוהים עם דור שלם. זמן קצר אחרי האלבום הצטרף ללהקה צעיר מג׳ורג׳יה בשם גראם פרסונס, והבירדס יצאו לכיוון אחר לגמרי: קאנטרי (אלבום 133).''',
'''הקשיבו מההתחלה ועד הסוף, כמו ליצירה אחת: שימו לב איך השירים זורמים זה לזה. ואחר כך השוו את Goin’ Back ל־My Back Pages באלבום 94: שני שירים של אנשים אחרים על געגוע לנעורים.''',
], [
('Goin’ Back', 'שיר של קרול קינג וג׳רי גופין על הרצון לחזור לתמימות של הילדות.'),
('Wasn’t Born to Follow', 'שיר קאנטרי־רוק על חופש, שנכנס לסרט "הנוסע המהיר".'),
('Draft Morning', 'שיר שקט ועצוב על צעיר שנקרא למלחמה, עם רעשי קרב ברקע.'),
])

add(120, [
'''ג׳ניס ג׳ופלין גדלה בעיירת נפט בטקסס, שם הרגישה זרה ודחויה, והקשיבה לזמרות בלוז כמו בסי סמית׳. ב־1966 היא הגיעה לסן פרנסיסקו והצטרפה ללהקה מקומית רועשת בשם Big Brother & the Holding Company. בפסטיבל מונטריי ב־1967 היא שרה את Ball and Chain בעוצמה כזאת שהקהל נדהם, ובן לילה הפכה לכוכבת. חברת Columbia החתימה את הלהקה, ו־Cheap Thrills יצא באוגוסט 1968, עם עטיפה מצוירת של אמן הקומיקס רוברט קראמב.''',
'''על העטיפה כתוב שהאלבום הוקלט בהופעה, אבל בעצם רק שיר אחד, Ball and Chain, הוקלט מול קהל. את השאר הקליטו באולפן, והוסיפו רעשי קהל כדי שיישמע חי. וזה בכל זאת נשמע חי מאוד: גיטרות פרועות ולא מלוטשות, ומעליהן הקול של ג׳ופלין, צרוד, צועק, שובר ונשבר. Piece of My Heart, שיר של ארמה פרנקלין, אחותה של ארית׳ה (אלבומים 106 ו־117), הופך אצלה לתחינה קורעת. Summertime, מתוך האופרה "פורגי ובס" של גרשווין, מתחיל כמעט כמו שיר ערש, ומתמלא בכאב.''',
'''האלבום עמד בראש המצעד האמריקאי שמונה שבועות. אבל ג׳ופלין עזבה את הלהקה זמן קצר אחר כך, והקליטה עוד שני אלבומים בלבד לפני שמתה באוקטובר 1970, בגיל 27, שבועות ספורים אחרי ג׳ימי הנדריקס. היא הייתה אחת הנשים הראשונות שהפכו לכוכבות רוק בזכות עצמן, וקולה השפיע על זמרות רבות שבאו אחריה.''',
'''שמעו את Summertime כאן, ואחר כך את My Man’s Gone Now באלבום 30, של ביל אוונס: שני שירים מאותה אופרה, אחד צועק ואחד כמעט שותק.''',
], [
('Piece of My Heart', 'תחינה קורעת לב, שבה ג׳ופלין צועקת ומתחננת בו בזמן.'),
('Summertime', 'שיר הערש של גרשווין, שמתחיל בשקט ומתמלא בכאב.'),
('Ball and Chain', 'השיר היחיד שהוקלט באמת מול קהל, בלוז איטי שמתפוצץ.'),
])

add(121, [
'''ג׳וזף בירד היה מלחין אוונגרד שלמד מוזיקולוגיה באוניברסיטה בלוס אנג׳לס, והסתובב בעולם של מלחינים ניסיוניים כמו ג׳ון קייג׳. ב־1967 הוא החליט להקים להקת רוק, אבל כזאת שלא דומה לשום להקה אחרת: עם הזמרת דורותי מוסקוביץ, חברתו דאז, עם כינור חשמלי, בס ותופים, ובלי אף גיטרה. במקומה, כלים אלקטרוניים ומכשירים שבנו בעצמם, שמעוותים ומשנים את הצליל. הם קראו לעצמם, בפשטות, The United States of America, והאלבום היחיד שלהם יצא ב־1968.''',
'''הצליל מוזר ויפה בו בזמן: פעמונים, קליופה של קרקס, צפירות, צלילי מכונות ורעשים אלקטרוניים, ומעליהם הקול הצלול, הקר והרגוע של מוסקוביץ, כמו זמרת פולק שנפלה לתוך מעבדה. The American Metaphysical Circus נפתח כמו תהלוכת קרקס שמתפרקת, Cloud Song הוא שיר חלומי ושקט, ו־Love Song for the Dead Ché הוא בלדה עצובה ויפהפייה לזכר צ׳ה גווארה. המילים מלאות בביקורת חריפה ומצחיקה על אמריקה, על הצרכנות ועל המלחמה.''',
'''הלהקה התפרקה כמה חודשים אחרי שהאלבום יצא, מתוך מריבות פנימיות, והאלבום נכנס רק לתחתית המצעד. אבל הוא נחשב היום לאחד מאלבומי הרוק הראשונים שבנו את הצליל שלהם סביב אלקטרוניקה, שנים לפני שהסינתיסייזר הפך לכלי רגיל. להקות רבות, בעיקר בשנות התשעים, גילו אותו מחדש ולמדו ממנו איך לשלב פופ עדין עם רעש אלקטרוני.''',
'''התחילו מ־Love Song for the Dead Ché, השיר השקט והנגיש ביותר, ורק אחר כך חזרו להתחלה. ושימו לב שאין כאן גיטרה בכלל: נסו לנחש מה יוצר כל צליל.''',
], [
('The American Metaphysical Circus', 'הפתיחה: תהלוכת קרקס אלקטרונית שמתפרקת ומתחברת מחדש.'),
('Love Song for the Dead Che', 'בלדה עצובה ויפהפייה, בקולה הצלול של דורותי מוסקוביץ.'),
('Cloud Song', 'שיר חלומי ושקט, שמרחף כמו ענן.'),
])

add(122, [
'''מאק רבנאק גדל בניו אורלינס, והתחיל כבר כנער לנגן בגיטרה ובפסנתר באולפני ההקלטה של העיר ובמועדונים שלה. אחרי שנפצע באצבע מירייה, הוא עבר לפסנתר, ובאמצע שנות השישים עבר ללוס אנג׳לס ועבד כנגן אולפן. חבר מניו אורלינס, המעבד הרולד בטיסט, השיג לו שעות אולפן פנויות שנשארו מהקלטות של סוני וצ׳ר, ושם הקליט רבנאק ב־1967 אלבום משלו, בדמות חדשה: "ד״ר ג׳ון, נוסע הלילה", על שם מכשף וודו אגדי מניו אורלינס של המאה ה־19.''',
'''Gris-Gris נשמע כמו טקס וודו בביצה, בלילה: תופים ומקצבים של ניו אורלינס, מקהלה שחוזרת על לחשים בצרפתית קריאולית, קלרינט, מנדולינה, כלי הקשה ורעשים מסתוריים, והקול הצרוד והמנומנם של ד״ר ג׳ון, שמדבר ושר כמו מכשף. Gris-Gris Gumbo Ya Ya פותח בהצגה עצמית מאיימת ומשעשעת, ו־I Walk on Guilded Splinters הוא שיר של כמעט שמונה דקות, מהפנט ומפחיד, שהפך לשיר המפורסם באלבום. זו פסיכדליה, אבל כזאת שצמחה מהשורשים העתיקים של ניו אורלינס.''',
'''כשראש חברת התקליטים שמע את האלבום, הוא לא הבין מה לעשות בו, וכמעט לא הוציא אותו. אבל הוא מצא לו קהל, ועם השנים הפך לקלאסיקה. ד״ר ג׳ון המשיך לקריירה ארוכה, עם להיטים, פרסים ושיתופי פעולה, והפך לשגריר של המוזיקה של ניו אורלינס בעולם. I Walk on Guilded Splinters הוקלט מאז בידי רבים.''',
'''שמעו את האלבום בלילה, עם אוזניות ובלי למהר. ואחר כך השוו אותו ל־Safe as Milk באלבום 83: עוד זמר עם קול מוזר ששואב מהבלוז הישן ולוקח אותו למקום אחר.''',
], [
('Gris-Gris Gumbo Ya Ya', 'הפתיחה: ד״ר ג׳ון מציג את עצמו בקול מאיים ומשועשע.'),
('I Walk on Guilded Splinters', 'שמונה דקות מהפנטות ומפחידות של טקס וודו.'),
('Mama Roux', 'שיר קצבי ושמח של ניו אורלינס, עם מקהלה שקוראת ועונה.'),
])

add(123, [
'''Iron Butterfly נוסדו בסן דייגו ב־1966, ועברו ללוס אנג׳לס כדי לנגן במועדונים של סאנסט סטריפ. את הלהקה הוביל הקלידן והזמר דאג אינגל. לפי הסיפור, שם השיר המפורסם שלהם נולד מטעות: אינגל, שיכור, ניסה להגיד "In the Garden of Eden", והמתופף רון בושי רשם את מה ששמע: "In-A-Gadda-Da-Vida". האלבום השני שלהם, שנקרא באותו שם, יצא ביוני 1968.''',
'''הצד הראשון של התקליט הוא חמישה שירים קצרים של רוק פסיכדלי עם עוגב, נעימים ולא יותר. אבל הצד השני הוא כולו שיר אחד: In-A-Gadda-Da-Vida, שבע־עשרה דקות. הוא נפתח בריף עוגב וגיטרה כבד ופשוט, שחוזר שוב ושוב, וממשיך לסולו עוגב שנשמע כמו כנסייה מסתורית, לסולו גיטרה, ולסולו תופים ארוך של רון בושי, מהראשונים ברוק שהגיעו לתקליט. ואז הכול חוזר לריף.''',
'''האלבום נשאר במצעד האמריקאי כמעט שלוש שנים, ומכר מיליוני עותקים. כשהוקם ב־1976 פרס "תקליט הפלטינה", זה היה האלבום הראשון שקיבל אותו. המבקרים לא תמיד אהבו אותו, אבל הוא נחשב לאחד מאבות הרוק הכבד וההבי מטאל, והריף שלו מוכר גם למי שמעולם לא שמע את שם הלהקה.''',
'''הקדישו לשיר הארוך שבע־עשרה דקות רצופות, ועקבו אחרי הריף שחוזר. ואחר כך השוו את העוגב של אינגל לעוגב של ריי מנזרק באלבום 93: שני עוגבים של לוס אנג׳לס, אחד כבד ואחד מסתורי.''',
], [
('In-A-Gadda-Da-Vida', 'שבע־עשרה דקות של ריף כבד, עוגב מסתורי וסולו תופים ארוך.'),
('Most Anything You Want', 'שיר פסיכדלי קצר וקליט, עם עוגב וגיטרה שמשוחחים.'),
('Flowers and Beads', 'שיר פופ פסיכדלי רך, כמעט תמים, מלא פרחים וחרוזים.'),
])

add(124, [
'''The Pretty Things היו מלונדון, ובאמצע שנות השישים נחשבו לגרסה פרועה ומחוספסת עוד יותר של הרולינג סטונס. הגיטריסט דיק טיילור אפילו ניגן בבס בגרסה הראשונה של הסטונס. ב־1967 הם עזבו את הבלוז הרועש ונכנסו לאולפני אבי רוד עם המפיק נורמן סמית׳, שהפיק גם את Pink Floyd (אלבום 89), והקליטו אלבום שמספר סיפור שלם. S.F. Sorrow יצא בדצמבר 1968.''',
'''הסיפור עוקב אחרי חייו של סבסטיאן פ. סורו, "סורו" כמו "צער", מלידתו בעיירה קטנה, דרך אהבה ראשונה, מלחמה, ואסון בספינת אוויר שבו נהרגת אהובתו, ועד לשיגעון ולבדידות בזקנה. המוזיקה משלבת רוק פסיכדלי עם גיטרות מעוותות, מלוטרון, הרמוניות, צלילים הפוכים ואפקטים של אולפן. בין השירים יש קטעי קריינות קצרים שמספרים את הסיפור. S.F. Sorrow Is Born נפתח בשמחה, ו־Private Sorrow הוא אחד השירים הקודרים והיפים באלבום.''',
'''S.F. Sorrow נחשב לאחד מאלבומי "אופרת הרוק" הראשונים, והוא יצא חודשים לפני Tommy של The Who (אלבום 144), שהפכה את הרעיון למפורסם. באמריקה הוא יצא רק שנה אחר כך, בחברה קטנה, ונכשל. רבים חושבים שהלהקה לא קיבלה את ההכרה שהגיעה לה, וזה אחד האלבומים שמבקרים מזכירים שוב ושוב כ"יהלום שנשכח".''',
'''הקשיבו מההתחלה ועד הסוף, כמו לספר. ואחר כך עברו לאלבום 144 והשוו: שני סיפורים על חיים שלמים באלבום אחד, מאותה שנה בערך.''',
], [
('S.F. Sorrow Is Born', 'הפתיחה: לידתו של הגיבור, בשיר שמח וצבעוני.'),
('Private Sorrow', 'שיר קודר ויפה על צער פרטי, מהשירים החזקים באלבום.'),
('Balloon Burning', 'האסון בספינת האוויר, עם גיטרות בוערות ורועשות.'),
])

add(125, [
'''אחרי ההצלחה של אלבום 71, פול סיימון וארט גרפונקל הפכו לכוכבים גדולים, ובמאי צעיר בשם מייק ניקולס ביקש מהם שירים לסרט שלו, "הבוגר". אחד מהם היה Mrs. Robinson, שנכתב במקור בשם אחר והותאם לסרט. הסרט יצא בסוף 1967 והצליח מאוד, ובאפריל 1968 יצא Bookends, האלבום הבא שלהם, שבו גם הגרסה המלאה של השיר.''',
'''הצד הראשון של התקליט הוא מעין סיפור על מהלך החיים, מהנעורים ועד הזקנה: Save the Life of My Child, עם סינתיסייזר מוג מאיים; America, על זוג צעיר שנוסע באוטובוס לחפש את אמריקה; Voices of Old People, הקלטות אמיתיות של זקנים בבית אבות שגרפונקל הקליט בעצמו; ו־Old Friends, על שני חברים זקנים על ספסל בפארק. הצד השני מלא בלהיטים, ביניהם Mrs. Robinson ו־A Hazy Shade of Winter.''',
'''Bookends הגיע למקום הראשון באמריקה ובבריטניה, ו־Mrs. Robinson היה ללהיט מספר אחד וזכה בגראמי. אבל השיר שהפך עם השנים לאהוב מכולם הוא America, שנחשב לאחד השירים היפים שנכתבו על ארצות הברית ועל הנעורים. האלבום מראה צמד שמתבגר: פחות פולק, יותר אולפן, ומבט עצוב ורגיש על הזמן שעובר.''',
'''הקשיבו לצד הראשון ברצף, כמו לחיים שלמים בעשרים דקות. ואחר כך חזרו לאלבום 71 ושמעו כמה השתנו סיימון וגרפונקל בשנה וחצי.''',
], [
('America', 'זוג צעיר באוטובוס, מחפש את אמריקה. אחד השירים היפים של סיימון.'),
('Mrs. Robinson', 'השיר מהסרט "הבוגר", קצבי ומלא הומור.'),
('Old Friends', 'שני חברים זקנים על ספסל בפארק, בשיר עדין ומצמרר.'),
])

add(126, [
'''Small Faces היו ארבעה צעירים קטנים בגובה ממזרח לונדון, ומכאן שמם. הם היו כוכבים של תנועת המודס, עם להיטים של רוק וסול, והזמר והגיטריסט סטיב מריוט, עם הקול הגדול והנשמתי שלו, נחשב לאחד הזמרים הטובים של אנגליה. ב־1968 הם הקליטו את Ogdens’ Nut Gone Flake, שיצא במאי, עם עטיפה עגולה שחיקתה קופסת טבק ישנה בשם דומה. האלבום עמד בראש המצעד הבריטי שישה שבועות.''',
'''הצד הראשון מלא בשירים עצמאיים: Lazy Sunday, להיט עליז ומצחיק שמריוט שר במבטא קוקני כבד, על שכנים רועשים ביום ראשון, Afterglow of Your Love, בלדת סול עוצמתית, ו־Song of a Baker, רוק כבד. הצד השני הוא סיפור אגדה: Happiness Stan, בחור שיוצא לחפש את חצי הירח שנעלם. בין השירים מספר את הסיפור הקומיקאי סטנלי אנווין, בשפה מומצאת ומצחיקה משלו, שנשמעת כמו אנגלית אבל מלאה במילים משובשות.''',
'''האלבום היה כל כך מורכב שהלהקה כמעט לא יכלה לבצע אותו בהופעות, וזה תסכל את מריוט. בתחילת 1969 הוא עזב והקים להקה חדשה, ושלושת האחרים המשיכו עם הזמר רוד סטיוארט והגיטריסט רון ווד (שניהם מאלבום 128) בשם The Faces. Ogdens’ נחשב לאחד מאלבומי הקונספט הבריטיים הגדולים של שנות השישים, ומלא בהומור שאין כמעט באף אלבום אחר מהתקופה.''',
'''שמעו את Lazy Sunday ונסו להבין כל מילה במבטא הקוקני. ואחר כך הקשיבו לצד השני ברצף, כמו להצגת ילדים מוזרה, ושימו לב לשפה של סטנלי אנווין.''',
], [
('Lazy Sunday', 'להיט עליז ומצחיק, במבטא קוקני כבד, על שכנים רועשים.'),
('Afterglow of Your Love', 'בלדת סול עוצמתית שמראה את הקול הגדול של סטיב מריוט.'),
('Happiness Stan', 'תחילת האגדה על בחור שמחפש את חצי הירח שנעלם.'),
])

add(127, [
'''The Band היו חמישה נגנים, ארבעה קנדים ומתופף אחד מארקנסו, שניגנו יחד שנים כלהקת ליווי של זמר רוקנרול, ואחר כך ליוו את בוב דילן בסיבוב ההופעות החשמלי שלו ב־1965–1966, שבו הקהל שרק ומחה בכל ערב. ב־1967 הם עברו לגור בבית ורוד גדול ליד וודסטוק, שכינו "ביג פינק", ובמרתף ניגנו והקליטו שירים עם דילן, שהתאושש שם מתאונת אופנוע (אלבום 64). משם הם יצאו לאלבום משלהם: Music From Big Pink יצא ביולי 1968.''',
'''בשנה של פסיכדליה, גיטרות רועשות וסולואים ארוכים, The Band עשו בדיוק ההפך: מוזיקה שנשמעת עתיקה, אמריקאית ומחוספסת, עם קאנטרי, גוספל, בלוז, פולק ורוקנרול, ושלושה זמרים שמתחלפים ושרים יחד בהרמוניות לא מלוטשות. העוגב של גארת׳ הדסון נשמע כמו כנסייה ישנה. The Weight הוא סיפור מוזר ומצחיק על אדם שמגיע לעיירה ונתקל בדמויות משונות, ו־I Shall Be Released של דילן, בקולו הגבוה והשבור של ריצ׳רד מנואל, הוא אחד השירים המרגשים של התקופה. את הציור על העטיפה צייר דילן עצמו.''',
'''האלבום לא הפך ללהיט ענק, אבל מוזיקאים שמעו אותו ושינו כיוון: אריק קלפטון אמר שהוא גרם לו לרצות לעזוב את Cream, וג׳ורג׳ הריסון בא לבקר את הלהקה בוודסטוק. בעקבותיו הרבה להקות חזרו מהפסיכדליה אל השורשים, ומה שקוראים היום "אמריקנה" צמח במידה רבה מהתקליט הזה.''',
'''שמעו את The Weight, ושימו לב לקולות שמצטרפים ומתחלפים בפזמון. ואחר כך השוו את I Shall Be Released ל־Just Like a Woman באלבום 64: דילן כותב, ואחרים שרים.''',
], [
('The Weight', 'סיפור מוזר ומצחיק על עיירה ודמויותיה, עם פזמון שכולם שרים יחד.'),
('I Shall Be Released', 'שיר של דילן על חופש וגאולה, בקולו השבור של ריצ׳רד מנואל.'),
('Tears of Rage', 'הפתיחה: בלדה איטית וכבדה שכתבו דילן ומנואל, על הורים וילדים.'),
])

add(128, [
'''ג׳ף בק, הגיטריסט הפרוע של הירדבירדס (אלבום 74), עזב את הלהקה בסוף 1966 והקים להקה משלו: הזמר הצעיר רוד סטיוארט, עם קול צרוד ונשמתי, רון ווד בבס, המתופף מיקי וולר, ובחלק מהשירים הפסנתרן ניקי הופקינס. Truth, האלבום הראשון שלהם, הוקלט בלונדון ויצא בקיץ 1968. באחד הקטעים, Beck’s Bolero, מנגנים עם בק ג׳ימי פייג׳, ג׳ון פול ג׳ונס וקית׳ מון, ששקלו אז להקים יחד להקה.''',
'''זה בלוז בריטי כבד ורועש, במהירות ובעוצמה חדשות: הגיטרה של בק צורחת, מתפתלת, מחקה קולות ומשתוללת, והקול של סטיוארט מתנגש בה ומשוחח איתה. יש כאן בלוז של ווילי דיקסון, כמו You Shook Me ו־I Ain’t Superstitious, לצד הפתעות: Greensleeves, שיר עם אנגלי עתיק לגיטרה אקוסטית, ו־Ol’ Man River, שיר ממחזמר אמריקאי ישן, בגרסה כבדה ואיטית. Beck’s Bolero מבוסס על הבולרו של ראוול.''',
'''Truth נחשב לאחד האלבומים שהניחו את היסודות של הרוק הכבד וההבי מטאל. כמה חודשים אחרי שיצא, ג׳ימי פייג׳ הקים את לד זפלין והקליט גם הוא את You Shook Me, לכעסו של בק. הלהקה של בק התפרקה אחרי אלבום נוסף, וסטיוארט ווד המשיכו ל־The Faces (אלבום 126) ולקריירות גדולות. בק עצמו המשיך עוד עשרות שנים כאחד הגיטריסטים המוערכים בעולם.''',
'''שמעו את You Shook Me כאן, ואחר כך את הגרסה של לד זפלין מאלבום הבכורה שלהם. ואז חזרו לבק של אלבום 74, ושמעו כמה השתנה בשנתיים.''',
], [
('Beck’s Bolero', 'קטע אינסטרומנטלי בהשראת ראוול, עם חברים שיקימו אחר כך את לד זפלין.'),
('You Shook Me', 'בלוז כבד של ווילי דיקסון, עם גיטרה וקול שמתווכחים.'),
('Greensleeves', 'שיר עם אנגלי עתיק, בגיטרה אקוסטית שקטה, הפתעה באמצע הרעש.'),
])

add(129, [
'''קאטאנו ולוזו גדל בעיירה קטנה בבאהיה שבצפון ברזיל, והגיע לריו ולסאו פאולו באמצע שנות השישים, יחד עם אחותו מריה בטאניה ועם חבריו ז׳ילברטו ז׳יל וגאל קוסטה. בפסטיבל טלוויזיה ב־1967 הוא שר את Alegria, Alegria עם להקת רוק חשמלית, וגרם לסערה: בעיני רבים, גיטרה חשמלית הייתה בגידה במוזיקה הברזילאית. אלבום הסולו הראשון שלו יצא בתחילת 1968, והשיר Tropicália שבו נתן את השם לתנועה כולה.''',
'''האלבום מערבב הכול: סמבה ובוסה נובה, רוק, מוזיקת תזמורת, מוזיקת רחוב ורדיו ישן, עם עיבודים של מעבדים שהגיעו מהמוזיקה הקלאסית המודרנית. Tropicália נפתח בקריינות מוזרה ובתופים, ומתאר את ברזיל כמו קולאז׳ של דימויים סותרים: מודרנית ועתיקה, עשירה וענייה. Alegria, Alegria הוא שיר קליל ושמח על צעיר שהולך ברחוב העיר, ו־Soy Loco por Ti, América, בספרדית ובפורטוגזית, הוא שיר אהבה ליבשת כולה, וגם מחווה לצ׳ה גווארה.''',
'''המשטר הצבאי לא אהב את הטרופיקליה. בסוף 1968 קאטאנו וז׳יל נעצרו, ובשנה שאחרי נאלצו לצאת לגלות בלונדון, לשנתיים וחצי. אבל התנועה שלהם שינתה את המוזיקה הברזילאית לתמיד, וקאטאנו הפך לאחד המוזיקאים והאינטלקטואלים החשובים בברזיל, עם קריירה של יותר מחמישים שנה.''',
'''שמעו את Tropicália ואחר כך את Panis et Circenses באלבום 112, של Os Mutantes: שני שירים של אותה תנועה, מאותה שנה, שניהם צוחקים על ברזיל ואוהבים אותה.''',
], [
('Tropicália', 'השיר שנתן את שמו לתנועה: קולאז׳ מוזר ושמח של ברזיל כולה.'),
('Alegria, Alegria', 'שיר קליל על צעיר שהולך ברחוב, עם הלהקה החשמלית שעוררה סערה.'),
('Soy Loco por Ti, América', 'שיר אהבה ליבשת כולה, בספרדית ובפורטוגזית, בקצב לטיני.'),
])

add(130, [
'''סקוט אנגל נולד באוהיו, וגדל בקליפורניה. באמצע שנות השישים הוא עבר ללונדון עם שני חברים, והשלושה, שלא היו אחים בכלל, הפכו ל־The Walker Brothers, עם בלדות עצובות ודרמטיות ומעריצות צורחות. סקוט, שאימץ את השם סקוט ווקר, שנא את התהילה, ובשנה הבאה פנה לקריירת סולו. הוא גילה באותה תקופה את השירים של ז׳אק ברל (אלבום 43), בתרגום לאנגלית, והתאהב בהם. Scott 2 יצא במרץ 1968, והגיע למקום הראשון במצעד הבריטי.''',
'''הקול של ווקר הוא בריטון עמוק, עשיר ועצוב, והוא עטוף בתזמורות גדולות ודרמטיות, בין מחזמר הוליוודי, שאנסון צרפתי ופסקול של סרט. Jackie, שיר של ברל על זמר שחולם להיות שוב צעיר ומושחת, נפתח את האלבום בפרץ של כלי נשיפה, והמילים שלו הביאו את ה־BBC להחרים אותו. Next, עוד שיר של ברל, קודר ומזעזע, על חייל צעיר בצבא. ולצדם שירים שווקר כתב בעצמו, כמו The Amorous Humphrey Plugg, על גבר משעמם שחולם על הרפתקאות.''',
'''Scott 2 היה אחד השיאים המסחריים של ווקר, אבל אחרי כמה שנים הוא התרחק לגמרי מהפופ, ובשנים המאוחרות הקליט אלבומים ניסיוניים וקודרים מאוד. זמרים רבים ראו בו מורה: דייוויד בואי, מארק אלמונד, ג׳ארוויס קוקר ואחרים. הוא הביא את ברל לקהל הבריטי, והראה שזמר פופ יכול לשיר שירים מסובכים, אפלים וספרותיים.''',
'''שמעו את Jackie, ואחר כך חזרו לברל עצמו באלבום 43: אותו עולם של שירים, בצרפתית ובאנגלית, בקול של משורר מבלגיה ובקול של אליל נוער אמריקאי.''',
], [
('Jackie', 'שיר של ברל על זמר שחולם לחזור לחיים המושחתים, בפרץ של כלי נשיפה.'),
('The Amorous Humphrey Plugg', 'שיר שכתב ווקר על גבר משעמם שחולם על הרפתקאות.'),
('Next', 'שיר קודר של ברל על חייל צעיר, בקול עמוק ומאיים.'),
])

add(131, [
'''The Zombies נוסדו בבית ספר בעיירה סנט אלבנס שליד לונדון, ובשנת 1964 כבר היה להם להיט עולמי, She’s Not There. אבל אחרי שלוש שנים בלי הצלחות גדולות, חברת התקליטים שלהם כמעט ויתרה עליהם. בקיץ 1967 הם נכנסו לאולפני אבי רוד, מיד אחרי שהביטלס סיימו שם את Sgt. Pepper (אלבום 78), עם תקציב קטן מאוד, והפיקו בעצמם את האלבום. בלי כסף לתזמורת, הם השתמשו במלוטרון, כלי מקלדת שמשמיע הקלטות של כינורות וחלילים, שהביטלס השאירו באולפן. בדצמבר 1967 הלהקה התפרקה, ארבעה חודשים לפני שהאלבום יצא.''',
'''זה פופ פסיכדלי עדין ויפה להפליא: הרמוניות קוליות מורכבות, פסנתר, מלוטרון, והקול הרך והאוורירי של קולין בלנסטון. את השירים כתבו הקלידן רוד ארג׳נט והבסיסט כריס וייט, והם מספרים סיפורים קטנים: Care of Cell 44 הוא מכתב אוהב ושמח לבחורה שעומדת לצאת מהכלא, A Rose for Emily על אישה שהזדקנה לבד, ו־Butcher’s Tale הוא שיר מצמרר על חייל בשוחות של מלחמת העולם הראשונה. ובסוף Time of the Season, עם הבס המפורסם, מחיאות הכפיים והנשימה בפתיחה.''',
'''בבריטניה האלבום נכשל. באמריקה חברת התקליטים כמעט לא הוציאה אותו, עד שהמוזיקאי אל קופר שמע אותו ושכנע אותם. בתחילת 1969 Time of the Season הפך בפתאומיות ללהיט ענק באמריקה, כשהלהקה כבר לא הייתה קיימת. עם השנים Odessey and Oracle, עם שגיאת הכתיב המפורסמת שעשה המעצב של העטיפה, הפך לאחד מאלבומי הפופ האהובים של שנות השישים.''',
'''השוו לאלבום 61, Pet Sounds: שני אלבומים של פופ עדין ומורכב על געגוע ועל התבגרות. ושמעו את Care of Cell 44 בבוקר שמש, כמו שהוא נשמע.''',
], [
('Care of Cell 44', 'מכתב אהבה שמח לבחורה שעומדת לצאת מהכלא, עם הרמוניות מתפרצות.'),
('A Rose for Emily', 'בלדה עדינה לפסנתר על אישה שהזדקנה לבד.'),
('Time of the Season', 'הלהיט שהגיע רק אחרי שהלהקה התפרקה: בס, מחיאות כפיים ונשימה.'),
])

add(132, [
'''ואן מוריסון גדל בבלפסט, בצפון אירלנד, ובאמצע שנות השישים שר בלהקת Them, עם הלהיט Gloria. ב־1967 הוא עבר לניו יורק והקליט להיט סולו, Brown Eyed Girl, עם המפיק ברט ברנס (אלבום 44), אבל נקלע לחוזה גרוע ולמאבקים עם החברה, ואחרי מותו הפתאומי של ברנס נשאר כמעט בלי כלום. הוא עבר לבוסטון, ניגן במועדונים קטנים, ובסוף חתם בחברת Warner. בספטמבר ובאוקטובר 1968, בכמה ערבים באולפן בניו יורק, הוא הקליט את Astral Weeks.''',
'''המפיק הביא לאולפן נגני ג׳אז מהשורה הראשונה, ביניהם הבסיסט ריצ׳רד דייוויס והגיטריסט ג׳יי ברלינר, שניגן גם עם מינגוס (אלבום 39), והם ניגנו שירים שמעולם לא שמעו קודם, סביב מוריסון והגיטרה האקוסטית שלו. התוצאה נשמעת כמו אלתור חי: בס שמשוטט, גיטרה, ויברפון, חליל, ומאוחר יותר נוספו כלי מיתר. ומוריסון שר כמו בטראנס, חוזר על מילים, ממלמל, צועק ולוחש, על זיכרונות מבלפסט, על אהבה, על ילדות ועל רגעים שלא חוזרים. Madame George ו־Cyprus Avenue הם שמות של מקומות ודמויות מהעיר שלו.''',
'''בזמנו האלבום כמעט לא נמכר. אבל עם השנים הוא הפך לאחד האלבומים הנערצים ביותר של שנות השישים, ומבקרים רבים מדרגים אותו בין הגדולים שהוקלטו אי פעם. הוא לא דומה לשום דבר אחר של אותה תקופה: לא פולק, לא רוק ולא ג׳אז, אלא משהו ביניהם. מוריסון המשיך לקריירה של עשרות אלבומים, אבל לרבים זה נשאר השיא.''',
'''הקשיבו מההתחלה ועד הסוף, בשקט, בלי לנסות להבין כל מילה. ושימו לב לבס של ריצ׳רד דייוויס: הוא כמעט קול שני באלבום.''',
], [
('Astral Weeks', 'שיר הנושא: גיטרה אקוסטית, בס משוטט וקול שממריא.'),
('Madame George', 'עשר דקות של זיכרון מבלפסט, על דמות מסתורית, שחוזר ומתעצם.'),
('The Way Young Lovers Do', 'שיר אהבה קליל וקופצני, עם כלי נשיפה וטעם של ג׳אז.'),
])

add(133, [
'''בתחילת 1968 הבירדס נשארו כמעט בלי חברים (אלבום 119), והם חיפשו נגן קלידים. מצאו צעיר מג׳ורג׳יה בשם גראם פרסונס, בן 21, שהיה מאוהב בקאנטרי. תוך כמה שבועות הוא שכנע את רוג׳ר מקגווין וכריס הילמן לעשות משהו שאף להקת רוק גדולה לא עשתה: אלבום קאנטרי שלם. הם הקליטו חלק ממנו בנאשוויל, עם נגני קאנטרי מקומיים, והופיעו אפילו בגראנד אול אופרי, הבמה הקדושה של הקאנטרי, מול קהל שלא אהב היפים עם שיער ארוך. Sweetheart of the Rodeo יצא באוגוסט 1968.''',
'''זה קאנטרי אמיתי, בלי אירוניה: גיטרת פדל סטיל, בנג׳ו, כינור, מנדולינה והרמוניות רכות. יש כאן שני שירים של בוב דילן, מההקלטות שלו במרתף בוודסטוק, שירים של האחים לובין (אלבום 3), של מרל הגארד (אלבום 99) ושירי עם ישנים. The Christian Life, על אמונה, מושר בכנות גמורה. Hickory Wind, שכתב פרסונס, הוא שיר געגוע עדין לבית בדרום. בגלל בעיה בחוזה של פרסונס, מקגווין שר מחדש חלק מהשירים שהוא שר במקור.''',
'''האלבום נמכר פחות מכל אלבום קודם של הבירדס, והקהל של הרוק לא הבין אותו, והקהל של הקאנטרי לא סמך עליו. פרסונס עזב אחרי חצי שנה. אבל היום Sweetheart of the Rodeo נחשב לאחד מאלבומי הקאנטרי־רוק החשובים הראשונים, והדרך שהוא פתח הובילה לפלאיינג בוריטו ברדרס (אלבום 140), לאיגלס, ולכל מה שנקרא היום "אמריקנה".''',
'''שמעו את Life in Prison כאן ואז את המקור של מרל הגארד באלבום 99, ואת The Christian Life ואז את האחים לובין באלבום 3. הבירדס מנגנים את הקאנטרי בכבוד, ואפשר לשמוע.''',
], [
('Hickory Wind', 'שיר געגוע עדין לבית בדרום, שכתב גראם פרסונס.'),
('You Ain’t Goin’ Nowhere', 'שיר של דילן מהמרתף בוודסטוק, קליל ושמח, עם גיטרת סטיל.'),
('The Christian Life', 'שיר של האחים לובין על אמונה, מושר בכנות גמורה.'),
])

add(134, [
'''ב־1967 פרנק זאפה ולהקתו The Mothers of Invention (אלבום 69) עברו לניו יורק והופיעו חודשים במועדון קטן בגריניץ׳ וילג׳. משם הם הסתכלו על "קיץ האהבה" בסן פרנסיסקו בחשדנות: לזאפה, שלא נגע בסמים ולא אהב אופנות, ההיפים נראו לא פחות צבועים ומשעממים מההורים שלהם. We’re Only in It for the Money, שיצא במרץ 1968, הוא סאטירה על שני הצדדים. העטיפה היא פרודיה מדויקת על העטיפה של Sgt. Pepper (אלבום 78).''',
'''האלבום בנוי כמו קולאז׳: שירים קצרים שעוברים זה לזה בלי הפסקה, שירי פופ מתוקים עם מילים חריפות, צלילים הפוכים, קטעי דיבור, צחוקים, רעשים וקטעי מוזיקה אוונגרדית. Who Needs the Peace Corps? צוחק על צעירים שבורחים לסן פרנסיסקו כדי להיות "היפים", Flower Punk הוא פרודיה על השיר Hey Joe (אלבומים 63 ו־100), ו־Mother People ו־Concentration Moon תוקפים את המשטרה ואת החברה האמריקאית. חברת התקליטים צנזרה כמה שורות.''',
'''זה אחד האלבומים הראשונים שעשו סאטירה על התרבות הנגדית מבפנים, והוא נשמע רלוונטי עד היום. מבחינה מוזיקלית הוא הראה שאלבום רוק יכול להיבנות כמו סרט ערוך, עם גזירות ומעברים, ולא רק כאוסף שירים. זאפה המשיך בדרך הזאת ובעשרות כיוונים אחרים עד מותו ב־1993, והשאיר יותר משישים אלבומים.''',
'''שמעו את Flower Punk ואחר כך את Hey Joe באלבום 100, ותבינו על מה הוא צוחק. ואז הסתכלו על העטיפה ליד העטיפה של אלבום 78.''',
], [
('Who Needs the Peace Corps?', 'סאטירה מצחיקה על צעירים שמתחפשים להיפים לסוף שבוע.'),
('Flower Punk', 'פרודיה מהירה ומטורפת על Hey Joe, על היפי מזויף.'),
('Mother People', 'שיר חריף על משפחה, חברה וצנזורה, שחלק ממנו צונזר.'),
])

add(135, [
'''אחרי שהתפרקו Buffalo Springfield (אלבום 80), ניל יאנג הוציא אלבום סולו ראשון, עדין ומלוטש, ולא היה מרוצה ממנו. בלוס אנג׳לס הוא הכיר להקה מקומית, והזמין שלושה מחבריה, הגיטריסט דני וויטן, הבסיסט בילי טלבוט והמתופף ראלף מולינה, לנגן איתו. הוא קרא להם Crazy Horse, על שם מנהיג אינדיאני. האלבום הוקלט בכמה שבועות ויצא במאי 1969. לפי הסיפור של יאנג, שלושה מהשירים הגדולים שבו נכתבו ביום אחד, כשהיה חולה במיטה עם חום גבוה.''',
'''הצליל של Crazy Horse פשוט, מחוספס ורועש: שתי גיטרות חשמליות, בס ותופים שמנגנים ביחד כמו מכונה אחת, בלי ליטוש ובלי דיוק מופגן. מעליהם הקול הגבוה והשביר של יאנג, והסולואים שלו, מעוותים, חוזרים על אותם צלילים, ומתפתלים במשך דקות ארוכות. Cinnamon Girl נפתח בריף כבד ופשוט, ושני השירים הארוכים, Down by the River ו־Cowgirl in the Sand, נמשכים כל אחד כעשר דקות, רובן ג׳אם של גיטרות. בין לבין יש שירים שקטים וכפריים יותר.''',
'''זה האלבום שבו ניל יאנג מצא את אחד משני הקולות שלו: הרועש, החשמלי והגולמי, לצד הצד האקוסטי והעדין. Crazy Horse ליוו אותו מאז, עם הפסקות, במשך עשרות שנים. הסולואים המחוספסים שלהם השפיעו על הפאנק ועל הגראנג׳, ויאנג קיבל מאוחר יותר את הכינוי "הסבא של הגראנג׳". דני וויטן מת ממנת יתר ב־1972.''',
'''שמעו את Cinnamon Girl, ואחר כך תנו ל־Down by the River עשר דקות שלמות, ושימו לב כמה מעט צלילים יאנג צריך בסולו. ואז השוו ל־Mr. Soul באלבום 80.''',
], [
('Cinnamon Girl', 'ריף כבד ופשוט, ושיר אהבה חשמלי וקצר.'),
('Down by the River', 'עשר דקות של ג׳אם, עם סולואים גולמיים ומילים מסתוריות.'),
('Cowgirl in the Sand', 'הסיום: ג׳אם ארוך ופרוע, עם גיטרות שמתחרות.'),
])

add(136, [
'''דון ואן פליט, קפטן ביפהארט (אלבום 83), שכר ב־1968 בית קטן בלוס אנג׳לס, והביא אליו את הלהקה שלו. במשך שמונה חודשים הם גרו שם יחד, ובמשך שעות ארוכות בכל יום התאמנו על עשרים ושמונה שירים שהוא הלחין: הוא שרק, ניגן בפסנתר שלא ידע לנגן בו, ושר את החלקים, והמתופף הפך אותם לתווים. הוא נתן לנגנים שמות חדשים, כמו Zoot Horn Rollo ו־Rockette Morton, שלט בהם בנוקשות, ולפעמים לא היה להם מה לאכול. חברו פרנק זאפה (אלבום 69) הפיק את האלבום לחברה שלו. Trout Mask Replica יצא ביוני 1969, כאלבום כפול.''',
'''שמיעה ראשונה נשמעת כמו כאוס: כל נגן מנגן בקצב אחר ובמפתח אחר, הגיטרות מתנגשות, ביפהארט צועק, משתעל, מדקלם שירה סוריאליסטית ומנגן סקסופון ובס קלרינט בפראות. אבל שום דבר כאן אינו מקרי: כל צליל תוכנן ונלמד בעל פה. מתחת לכל זה יש בלוז של הדלתא, ג׳אז חופשי ושירה אמריקאית. Moonlight on Vermont הוא אחד השירים הנגישים יותר, China Pig הוא בלוז אקוסטי שהוקלט בבית, ו־Orange Claw Hammer הוא שיר ים שביפהארט שר לבד, בלי ליווי.''',
'''האלבום כמעט לא נמכר, ורבים מאזינים בו עד היום פעם אחת ולא מבינים. אבל הוא נחשב לאחד האלבומים המקוריים והמשפיעים ביותר בתולדות הרוק: הפאנק, הניו ווייב והרוק הניסיוני, ממוזיקאים כמו טום ווייטס ועד להקות פוסט־פאנק רבות, למדו ממנו שהכללים של הרוק לא חייבים להישאר.''',
'''תנו לאלבום שלוש שמיעות לפני שתחליטו. התחילו מ־Moonlight on Vermont ו־China Pig, ורק אחר כך עברו לשאר. ואם זה קשה מדי, חזרו ל־Safe as Milk באלבום 83, ושמעו מאיפה זה התחיל.''',
], [
('Moonlight on Vermont', 'אחד השירים הנגישים באלבום: בלוז פרוע עם גיטרות שמתווכחות.'),
('China Pig', 'בלוז אקוסטי שהוקלט בבית, עם גיטרה אחת וקול גדול.'),
('Ella Guru', 'שיר מצחיק ומסובך, עם גיטרות שמשתלבות כמו פאזל.'),
])

add(137, [
'''Creedence Clearwater Revival הגיעו מאל סריטו, פרבר שקט ליד סן פרנסיסקו, ולא מלואיזיאנה כמו שרבים חשבו כששמעו אותם. ג׳ון פוגרטי, אחיו טום, הבסיסט סטו קוק והמתופף דאג קליפורד ניגנו יחד מאז התיכון. בזמן שהלהקות בעיר ניגנו ג׳אמים פסיכדליים ארוכים, פוגרטי כתב שירים קצרים ופשוטים על דרום אמריקה שהוא דמיין מתוך תקליטי בלוז, סרטים וספרים: ביצות, נהרות, ספינות קיטור. Bayou Country, האלבום השני שלהם, יצא בינואר 1969.''',
'''הצליל פשוט וחזק: גיטרה חשמלית עם הדהוד, בס, תופים, והקול הצרוד והעוצמתי של ג׳ון פוגרטי, שנשמע כמו זמר בלוז מבוגר מהדרום. Born on the Bayou נפתח בריף גיטרה עבה ובאווירה של לילה חם בביצה. Proud Mary הוא שיר על ספינת קיטור ועל אדם שעוזב עבודה בעיר ויוצא לנהר, וב־Good Golly Miss Molly של ליטל ריצ׳רד הם חוזרים לשורשים. Keep On Chooglin׳, בסוף, הוא ג׳אם של כמעט שמונה דקות, עם מפוחית.''',
'''Proud Mary הגיע למקום השני במצעד האמריקאי, הראשון מתוך חמישה שירים שלהם שהגיעו למקום השני ואף פעם לא לראשון. בשנה אחת, 1969, הם הוציאו שלושה אלבומים, והפכו לאחת הלהקות הגדולות באמריקה. Proud Mary הוקלט מאז שוב ושוב, והגרסה של טינה טרנר היא אולי המפורסמת שבהן.''',
'''שמעו את Good Golly Miss Molly כאן, ואחר כך את המקור של ליטל ריצ׳רד באלבום 14 ואת ג׳רי לי לואיס באלבום 48. שלוש גרסאות, שלוש אנרגיות. ואחר כך המשיכו לאלבום 142, שיצא באותה שנה.''',
], [
('Born on the Bayou', 'ריף עבה, לילה חם, ושיר על ילדות בביצה שפוגרטי מעולם לא ראה.'),
('Proud Mary', 'שיר על ספינת קיטור על הנהר, והלהיט הגדול הראשון שלהם.'),
('Keep On Chooglin’', 'ג׳אם של כמעט שמונה דקות, עם מפוחית וגיטרה שלא עוצרות.'),
])

add(138, [
'''דייוויד קרוסבי פוטר מהבירדס (אלבום 94), סטיבן סטילס נשאר בלי להקה אחרי שבאפלו ספרינגפילד התפרקו (אלבום 80), וגרהאם נאש, מהלהקה הבריטית The Hollies, חיפש משהו חדש. ב־1968, בערב בלוס אנג׳לס, הם שרו יחד בפעם הראשונה, והבינו מיד שההרמוניה של שלושת הקולות שלהם היא משהו מיוחד. נאש עזב את להקתו ועבר לאמריקה. האלבום הראשון שלהם יצא במאי 1969. סטילס ניגן בו כמעט בכל הכלים בעצמו, עם מתופף אורח.''',
'''האלבום נפתח ב־Suite: Judy Blue Eyes, שיר של יותר משבע דקות בכמה חלקים, שסטילס כתב על הזמרת ג׳ודי קולינס, עם גיטרות אקוסטיות מבריקות והרמוניות מושלמות. Marrakesh Express של נאש קליל ושמח, על רכבת במרוקו. Guinnevere של קרוסבי שקט ומסתורי, Wooden Ships מדמיין את העולם אחרי מלחמה גרעינית, ו־Long Time Gone, שכתב קרוסבי אחרי רצח רוברט קנדי, כועס ועצוב. הכול נשען על שלושת הקולות.''',
'''האלבום הצליח מאוד, והשלושה זכו בגראמי לאמן החדש. כמה חודשים אחר כך הצטרף אליהם ניל יאנג, וההופעה השנייה שלהם כרביעייה הייתה בפסטיבל וודסטוק. ההרמוניות האקוסטיות שלהם השפיעו מאוד על הצליל של קליפורניה בשנות השבעים, מהאיגלס ועד פליטווד מק.''',
'''שמעו את Suite: Judy Blue Eyes, ונסו לעקוב אחרי כל אחד משלושת הקולות בנפרד. ואחר כך חזרו לבירדס באלבום 94 ולבאפלו ספרינגפילד באלבום 80, ותשמעו מאיפה הגיעו קרוסבי וסטילס.''',
], [
('Suite: Judy Blue Eyes', 'שבע דקות בכמה חלקים, עם גיטרות אקוסטיות והרמוניות מושלמות.'),
('Wooden Ships', 'שיר על העולם אחרי מלחמה גרעינית, ועל מי שבורחים בספינה.'),
('Guinnevere', 'שיר שקט ומסתורי של קרוסבי, בשני קולות בלבד.'),
])

add(139, [
'''Blood, Sweat & Tears נוסדו בניו יורק ב־1967 בידי אל קופר, הקלידן שניגן עם בוב דילן (אלבום 58), מתוך רעיון לחבר להקת רוק עם קבוצת כלי נשיפה כמו בלהקות ג׳אז. אחרי האלבום הראשון קופר עזב, והלהקה מצאה זמר קנדי עם קול כבד ועוצמתי, דייוויד קלייטון־תומאס. האלבום השני, שנקרא בשם הלהקה, יצא בדצמבר 1968, והפך לאחד האלבומים הנמכרים של השנה שאחרי.''',
'''הצליל מחבר רוק, ג׳אז, סול, בלוז ואפילו מוזיקה קלאסית: חצוצרות, טרומבונים וסקסופונים בעיבודים מורכבים, מעל להקת רוק, והקול הצרוד והגדול של קלייטון־תומאס. האלבום נפתח ונסגר בעיבוד ליצירה של המלחין הצרפתי אריק סאטי. Spinning Wheel, שכתב הזמר, הוא שיר קצבי עם כלי נשיפה עליזים. You’ve Made Me So Very Happy הוא להיט של מוטאון, ו־And When I Die, שכתבה לורה נירו (אלבום 116), הוא שיר שמח על המוות. יש גם גרסה ל־God Bless the Child של בילי הולידיי.''',
'''שלושה סינגלים מהאלבום הגיעו כולם למקום השני במצעד האמריקאי, והאלבום עצמו עמד בראש המצעד כמה שבועות. בפרס הגראמי לאלבום השנה הוא ניצח את Abbey Road של הביטלס (אלבום 143), החלטה שעדיין מתווכחים עליה. הלהקה פתחה את הדרך ל"ג׳אז־רוק", ולהקות כמו Chicago הלכו בעקבותיה.''',
'''שמעו את And When I Die, ואחר כך את לורה נירו באלבום 116: אותה כותבת, והשיר הזה, הפעם עם כלי נשיפה. ואת God Bless the Child חפשו גם בקולה של בילי הולידיי, שכתבה אותו (אלבום 16 הוא אלבום שלה).''',
], [
('Spinning Wheel', 'שיר קצבי עם כלי נשיפה עליזים, אחד הלהיטים הגדולים של 1969.'),
('And When I Die', 'שיר שמח על המוות, שכתבה לורה נירו.'),
('You’ve Made Me So Very Happy', 'להיט של מוטאון, בגרסה גדולה עם כלי נשיפה וקול עוצמתי.'),
])

add(140, [
'''גראם פרסונס עזב את הבירדס ב־1968 (אלבום 133), וכריס הילמן עזב אחריו. השניים הקימו להקה חדשה, The Flying Burrito Brothers, עם הבסיסט כריס אתרידג׳ ונגן גיטרת הפדל סטיל סניקי פיט קלנאו. הם הופיעו בחליפות קאנטרי מבריקות ורקומות, כמו של כוכבי נאשוויל, אבל עם עלי מריחואנה, כדורים ונשים עירומות רקומים עליהן. The Gilded Palace of Sin, האלבום הראשון שלהם, יצא בתחילת 1969.''',
'''זה קאנטרי, אבל של היפים מלוס אנג׳לס: גיטרת הפדל סטיל של קלנאו מעוותת לפעמים כמו גיטרה חשמלית של רוק, וההרמוניות של פרסונס והילמן הן של האחים לובין (אלבום 3) ושל האחים אוורלי (אלבום 27). Sin City הוא שיר עצוב ויפה על לוס אנג׳לס כעיר של חטא, ו־Hot Burrito #1 ו־#2 הם שירי אהבה שבורים. יש גם שני שירי סול דרומיים, ביניהם Do Right Woman, Do Right Man, שארית׳ה פרנקלין שרה (אלבום 106), בגרסת קאנטרי.''',
'''האלבום מכר מעט מאוד, אבל השפיע על אנשים רבים: הרולינג סטונס היו חברים של פרסונס ולמדו ממנו קאנטרי, והאיגלס, אמיילו האריס וזמרי האמריקנה הלכו בדרכו. פרסונס קרא לזה "מוזיקה אמריקאית קוסמית": קאנטרי, סול ורוק באותה נשימה. הוא מת ב־1973, בגיל 26.''',
'''שמעו את Do Right Woman, Do Right Man כאן ואחר כך את ארית׳ה באלבום 106: אותו שיר, בקאנטרי ובסול. ואחר כך את Sin City, ונסו לדמיין את החליפות.''',
], [
('Sin City', 'שיר עצוב ויפה על לוס אנג׳לס כעיר של חטא, בהרמוניה של שני קולות.'),
('Hot Burrito #1', 'בלדה שבורה של פרסונס, אחת הזעקות היפות של הקאנטרי־רוק.'),
('Do Right Woman', 'שיר הסול של ארית׳ה, בגרסת קאנטרי עם גיטרת סטיל.'),
])

add(141, [
'''אחרי ההצלחה של At Folsom Prison (אלבום 115), ג׳וני קאש חזר לרשימת המופיעים הגדולים, עם תוכנית טלוויזיה משלו ועם ג׳ון קרטר, שהפכה לאשתו. ב־24 בפברואר 1969 הוא הופיע בכלא סן קוונטין בקליפורניה, כלא שבו כבר הופיע בעבר, וצוות של הטלוויזיה הבריטית צילם סרט תיעודי. איתו על הבמה היו ג׳ון קרטר, קארל פרקינס, להקת הקולות The Statler Brothers ומשפחת קרטר.''',
'''זה מופע קשה וכועס יותר מפולסום: קאש עייף, רגזן ומתגרה בסוהרים, והאסירים שואגים בכל פעם שהוא מקלל את המערכת. הוא שר שיר שכתב במיוחד להופעה, San Quentin, שבו הוא אומר לכלא עצמו שהוא שונא אותו, והקהל מתפרץ כל כך שהוא שר אותו פעם שנייה. והרגע המפורסם ביותר הוא A Boy Named Sue, שיר קומי שכתב של סילברסטין, סופר ומאייר של ספרי ילדים, על ילד שאביו קרא לו "סו", שם של בנות, כדי להקשיח אותו. קאש שר אותו בפעם הראשונה בחייו, כמעט מקריא מדף המילים, והקהל צוחק כל הדרך.''',
'''A Boy Named Sue הגיע למקום השני במצעד האמריקאי, והיה הלהיט הגדול ביותר בקריירה של קאש. האלבום עצמו הגיע למקום הראשון במצעד האלבומים הכללי, הפעם היחידה שקאש הגיע לשם, והביא את קולם של האסירים אל מחוץ לחומות. יחד עם פולסום, זה הזוג המפורסם ביותר של אלבומי הופעה בבתי כלא.''',
'''השוו לאלבום 115: אותו זמר, שנה אחר כך, כלא אחר. שימו לב כמה קאש כאן כועס יותר, וכמה הקהל שלו מרגיש שהוא חלק ממנו.''',
], [
('A Boy Named Sue', 'שיר קומי על ילד בשם "סו", שקאש שר לראשונה מול האסירים. הלהיט הגדול שלו.'),
('San Quentin', 'שיר זועם שכתב לכלא עצמו, והקהל דרש לשמוע אותו פעמיים.'),
('Wanted Man', 'שיר שכתבו יחד קאש ובוב דילן, על אדם שמבוקש בכל מקום.'),
])

add(142, [
'''1969 הייתה השנה הגדולה של Creedence Clearwater Revival: שלושה אלבומים, להיט אחרי להיט, ומקום בפסטיבל וודסטוק. Green River, האלבום השלישי שלהם, יצא באוגוסט, שבעה חודשים אחרי Bayou Country (אלבום 137). ג׳ון פוגרטי כתב, שר, ניגן בגיטרה, עיבד והפיק כמעט הכול בעצמו, ועבד עם הלהקה בקצב של צבא: חזרות כל יום, בלי ג׳אמים ובלי בזבוז זמן.''',
'''זה אולי האלבום המהודק ביותר שלהם: תשעה שירים קצרים, פחות מחצי שעה, כולם בנויים על ריפים פשוטים ועל הקול הצרוד של פוגרטי. Green River הוא שיר נוסטלגי על מקום של חופשה מהילדות, עם גיטרה רוטטת. Bad Moon Rising נשמע כמו שיר שמח וקופצני, אבל מדבר על סערה, רעידות אדמה וחורבן שמתקרבים. Lodi הוא שיר מר ומצחיק על מוזיקאי שנתקע בעיירה קטנה, מנגן בבארים ולא מצליח לצאת. ו־Wrote a Song for Everyone הוא שיר שקט ומתוסכל על חוסר היכולת לדבר עם מי שקרוב אליך.''',
'''Bad Moon Rising ו־Green River הגיעו שניהם למקום השני במצעד האמריקאי, והאלבום עצמו הגיע למקום הראשון. CCR הפכו לאחת הלהקות הנמכרות בעולם, עם צליל שנשמע כמו רוקנרול של שנות החמישים בזמן שכולם ניגנו פסיכדליה. הלהקה התפרקה ב־1972 בגלל מריבות, אבל השירים שלה נשמעים ברדיו ובסרטים עד היום.''',
'''שמעו את Bad Moon Rising והקשיבו למילים: מה אתם שומעים, שמחה או אזהרה? ואחר כך השוו את Lodi לחיים של להקות כמו Moby Grape (אלבום 81), שנתקעו אחרי רגע של הצלחה.''',
], [
('Bad Moon Rising', 'שיר קופצני ושמח שמדבר על חורבן שמתקרב.'),
('Green River', 'שיר נוסטלגי על מקום של חופשה מהילדות, עם גיטרה רוטטת.'),
('Lodi', 'שיר מר ומצחיק על מוזיקאי שנתקע בעיירה קטנה.'),
])

add(143, [
'''בתחילת 1969 הביטלס היו על סף פירוק: הם ניסו להקליט אלבום "חוזר לשורשים" מול מצלמות, והתוצאה הייתה ויכוחים, מתח ושעות של הקלטות שאיש לא רצה לערוך (הן יצאו אחר כך כ־Let It Be). באביב פול מקרטני פנה למפיק ג׳ורג׳ מרטין וביקש להקליט אלבום אחד נוסף, "כמו פעם". בקיץ 1969 הם חזרו לאולפני אבי רוד, ותוך כמה חודשים הקליטו את Abbey Road, שיצא בספטמבר. זה האלבום האחרון שהארבעה הקליטו יחד.''',
'''הצד הראשון מלא בשירים של כל אחד מהם: Come Together של לנון, עם בס כבד ומסתורי, Something של ג׳ורג׳ הריסון, אחד משירי האהבה היפים שנכתבו, Octopus’s Garden של רינגו, ו־I Want You (She’s So Heavy), שמסתיים בריף שחוזר ומתעצם עד שהוא נקטע באמצע. הצד השני הוא מחרוזת ארוכה: שירים קצרים וחצאי שירים שמתחברים לרצף ארוך אחד, מ־Here Comes the Sun של הריסון ו־Because עם שלושה קולות משוכפלים, ועד The End, עם סולו התופים היחיד של רינגו ושלושה סולואי גיטרה שבהם ג׳ון, פול וג׳ורג׳ מתחלפים.''',
'''Abbey Road היה אחד האלבומים הנמכרים של הביטלס, ורבים רואים בו את השיא המוזיקלי שלהם. העטיפה, ארבעה אנשים חוצים מעבר חציה ליד האולפן, הפכה לאחת התמונות המפורסמות בעולם, ומעבר החציה הפך לאתר תיירות. באפריל 1970 מקרטני הודיע שהוא עוזב, והביטלס הגיעו לסופם.''',
'''שמעו את הצד השני, מ־Here Comes the Sun ועד הסוף, ברצף ובלי הפסקה: זה הפרידה של הביטלס. ואחר כך חזרו לאלבום 35, וחשבו כמה רחוק הם הגיעו בשש שנים בלבד.''',
], [
('Something', 'שיר האהבה של ג׳ורג׳ הריסון, מהיפים שכתבה הלהקה.'),
('Here Comes the Sun', 'שיר של הריסון על שמש שחוזרת אחרי חורף ארוך, שנכתב בגינה של חבר.'),
('Come Together', 'הפתיחה: בס כבד, "שששש" מסתורי ומילים שאי אפשר להבין עד הסוף.'),
])

add(144, [
'''פיט טאונשנד, הכותב של The Who, חלם שנים לכתוב יצירה ארוכה שתספר סיפור אחד, מעין אופרה של רוק. כבר ב־Rael (אלבום 90) הוא ניסה את זה בקטן. באותן שנים הוא התקרב לתורה של מורה רוחני הודי בשם מהר באבא, והרעיונות שלו על תודעה, שקט ורוחניות נכנסו לסיפור. אחרי חודשים באולפן, Tommy יצא במאי 1969, כאלבום כפול. באותה שנה The Who ביצעו אותו בפסטיבל וודסטוק ובהופעות רבות, ברצף מלא.''',
'''הסיפור מוזר: טומי, ילד בריטי, רואה את אביו הורג את המאהב של אמו, וההורים אומרים לו שלא ראה ולא שמע. מההלם הוא הופך לחירש, אילם ועיוור. הוא גדל בעולם סגור, עובר התעללויות, ומגלה כישרון מוזר: הוא אלוף במשחק פינבול. אחרי שהוא נרפא, הוא הופך למנהיג רוחני עם מאמינים, שבסוף מתמרדים נגדו. Pinball Wizard הוא הלהיט, עם גיטרה אקוסטית מהירה, ו־See Me, Feel Me / We’re Not Gonna Take It הוא סיום גדול ומרומם, כמו תפילה.''',
'''Tommy היה ההצלחה הגדולה הראשונה של The Who באמריקה, והפך את "אופרת הרוק" לרעיון מפורסם, אחרי ניסיונות מוקדמים כמו S.F. Sorrow (אלבום 124). הסיפור עבר גלגולים רבים: ביצוע עם תזמורת סימפונית, סרט קולנוע ב־1975 עם כוכבים רבים, ומחזמר בברודווי בשנות התשעים. הוא הראה שאלבום רוק יכול להיות יצירה בקנה מידה של אופרה, וזה השפיע על הרוק המתקדם של שנות השבעים.''',
'''הקשיבו ל־Overture בהתחלה: היא מציגה את המנגינות של כל האופרה, כמו באופרה קלאסית. ונסו לזהות אותן כשהן חוזרות בהמשך. ואחר כך השוו ל־S.F. Sorrow באלבום 124.''',
], [
('Pinball Wizard', 'הלהיט: גיטרה אקוסטית מהירה, ועולם הפינבול של טומי.'),
('Overture', 'הפתיחה, שמציגה את המנגינות של כל האופרה, כמו באופרה קלאסית.'),
('We’re Not Gonna Take It', 'הסיום הגדול, שמסתיים ב"See me, feel me", כמו תפילה.'),
])

add(145, [
'''בסוף שנות השישים מיילס דייוויס (אלבומים 12 ו־21) שמע את ג׳ימי הנדריקס, את סליי סטון ואת ג׳יימס בראון, והבין שהג׳אז צריך להשתנות. הוא התחיל לנגן עם כלים חשמליים, ובפברואר 1969, בסשן אחד בניו יורק, הקליט את In a Silent Way עם צוות של כוכבים עתידיים: שלושה קלידנים על פסנתרים חשמליים ועוגב, ג׳ו זאווינול, הרבי הנקוק וצ׳יק קוריאה; הגיטריסט הבריטי ג׳ון מקלפלין, שהגיע לאמריקה זמן קצר קודם; ויין שורטר בסקסופון; דייב הולנד בבס; וטוני וויליאמס בתופים.''',
'''באלבום יש רק שני קטעים, כמעט עשרים דקות כל אחד. הם לא בנויים כמו שירי ג׳אז רגילים, עם נושא, סולואים וחזרה לנושא, אלא כמו מרחב: פסנתרים חשמליים שמרצדים כמו אור על מים, גיטרה שמנגנת צלילים בודדים, תופים שמתופפים בשקט על המצלתיים, ומעל הכול החצוצרה של מיילס, רכה ונוגה. המפיק טאו מאסרו חתך את ההקלטות, חזר על קטעים והדביק אותם זה לזה, כך שחלק מהמוזיקה שאתם שומעים חוזרת פעמיים, כמו באולפן של רוק.''',
'''חלק ממבקרי הג׳אז כעסו: פסנתרים חשמליים וגיטרה חשמלית בג׳אז? אבל האלבום פתח את התקופה החשמלית של מיילס, ואת הסגנון שנקרא אחר כך "פיוז׳ן". כמעט כל אחד מהנגנים הקים אחר כך להקה חשובה משלו. זה אלבום שנשמע לפעמים יותר כמו מוזיקת אווירה מאשר ג׳אז, וזה בדיוק היופי שלו.''',
'''הקשיבו בחושך, בשקט, בלי לחכות שמשהו "יקרה": תנו לזה לזרום. ואחר כך חזרו ל־Kind of Blue באלבום 21, עשר שנים קודם, ושמעו איך מיילס מחפש שוב את אותו שקט, בדרך אחרת לגמרי.''',
], [
('Shhh / Peaceful', 'קטע ארוך ורגוע, עם פסנתרים חשמליים שמרצדים וחצוצרה נוגה.'),
('In a Silent Way / It’s About That Time', 'פתיחה שקטה כמו שחר, שמתחממת לגרוב שמזכיר רוק וסול, ואז חוזרת לשקט.'),
])

add(146, [
'''הבי ג׳יז היו שלושה אחים, בארי, רובין ומוריס גיב, שנולדו באי מאן, גדלו במנצ׳סטר, והיגרו עם הוריהם לאוסטרליה, שם התחילו לשיר בילדותם. ב־1967 הם חזרו לאנגליה, והפכו תוך שנה לכוכבים, עם בלדות עצובות והרמוניות של שלושה אחים. Odessa, האלבום הכפול שלהם, הוקלט ב־1968 ויצא במרץ 1969, עטוף בעטיפה של קטיפה אדומה עם אותיות זהב. במהלך ההקלטות גבר המתח בין האחים, ורובין עזב את הלהקה זמן קצר אחרי שהאלבום יצא, אחרי ויכוח על השיר שנבחר לסינגל.''',
'''זה אלבום פופ שאפתני ומפואר, עם תזמורת גדולה, פסנתר, גיטרות אקוסטיות והרמוניות קוליות. Odessa (City on the Black Sea), שפותח את האלבום, הוא שיר ארוך ומוזר על ניצול מספינה שטבעה, בסגנון בלדה ימית עתיקה. First of May הוא בלדה עדינה של בארי על אהבת ילדות, ו־Lamplight הוא שיר דרמטי של רובין. Melody Fair הוא שיר פופ מתוק ורך, ו־Marley Purt Drive כבר נשמע כמו קאנטרי.''',
'''בזמנו האלבום קיבל ביקורות מעורבות ולא מכר כמו קודמיו, ואחרי הפירוק הזמני הבי ג׳יז נשכחו למדי. בשנות השבעים הם חזרו בגדול, עם הדיסקו של "קדחת מוצאי שבת", והפכו לאחת הלהקות הנמכרות בהיסטוריה. עם השנים, Odessa זכה להערכה מחודשת כאחד מאלבומי הפופ הבריטיים המפוארים של סוף שנות השישים, רחוק מאוד מהדיסקו.''',
'''שמעו את Odessa (City on the Black Sea) ואת First of May, ושכחו לרגע את "קדחת מוצאי שבת". ואחר כך השוו ל־Scott 2 באלבום 130: עוד פופ בריטי גדול עם תזמורת ועצב.''',
], [
('Odessa (City on the Black Sea)', 'שיר ארוך ומוזר על ניצול מספינה שטבעה, כמו בלדה ימית עתיקה.'),
('First of May', 'בלדה עדינה של בארי על אהבת ילדות ועל עץ חג המולד.'),
('Melody Fair', 'שיר פופ מתוק ורך על נערה שצריכה ללמוד לחייך.'),
])

add(147, [
'''Pentangle נוסדו בלונדון ב־1967, כחמישייה של נגנים מוכשרים במיוחד: שני הגיטריסטים ברט ג׳אנש (אלבום 56) וג׳ון רנבורן, הזמרת ג׳קי מקשי, עם קול צלול ומתוק, הבסיסט דני תומפסון והמתופף טרי קוקס, שניהם מעולם הג׳אז. השם, מחומש, בא ממספר החברים. Basket of Light, האלבום השלישי שלהם, יצא באוקטובר 1969, בהפקה של של טאלמי, שהפיק את The Who (אלבום 59).''',
'''הצליל מחבר שירי עם אנגליים וסקוטיים עתיקים עם ג׳אז, בלוז ואפילו מוזיקה של ימי הביניים: שתי גיטרות אקוסטיות שמשתלבות ומתפתלות זו סביב זו, קונטרבס שמנגן בחופש של ג׳אז, תופים רכים, וקולה של מקשי מעל הכול. Light Flight, שיר קצבי ומלא שמחה, הפך לשיר הנושא של סדרת טלוויזיה בריטית והביא אותם לקהל רחב. House Carpenter ו־Once I Had a Sweetheart הם בלדות עממיות עתיקות על אהבה ובגידה, ו־Train Song הוא קטע אינסטרומנטלי מסובך בקצבים משתנים.''',
'''האלבום הגיע לחמישייה הראשונה במצעד הבריטי, השיא המסחרי של הלהקה. Pentangle הראו שהפולק הבריטי יכול להיות מתוחכם כמו ג׳אז, והשפיעו על להקות פולק־רוק ועל גיטריסטים רבים. דני תומפסון, הבסיסט, ניגן באותה שנה גם באלבום הבכורה של ניק דרייק (אלבום 149).''',
'''הקשיבו ל־Light Flight ושימו לב לקצב, שמשתנה כל הזמן בלי שכמעט מרגישים. ואחר כך חזרו לברט ג׳אנש באלבום 56, ושמעו אותו לבד, ארבע שנים קודם.''',
], [
('Light Flight', 'שיר קצבי ושמח בקצבים משתנים, שהפך לשיר נושא של סדרת טלוויזיה.'),
('House Carpenter', 'בלדה עממית עתיקה על אישה שעוזבת את משפחתה, עם בנג׳ו וסיטאר.'),
('Once I Had a Sweetheart', 'שיר עם עצוב ויפה, בקולה הצלול של ג׳קי מקשי.'),
])

add(148, [
'''1969 הייתה שנה קשה לרולינג סטונס: בריאן ג׳ונס, מייסד הלהקה, פוטר בקיץ ומת כמה שבועות אחר כך, בגיל 27. את מקומו תפס הגיטריסט הצעיר מיק טיילור, שמנגן בשני שירים באלבום. בהמשך אותה שנה, תקופה של מלחמה, מהומות ותחושה שחלום שנות השישים מתפרק, הם סיימו את Let It Bleed, שיצא בדצמבר 1969, יום לפני הופעה בפסטיבל אלטמונט בקליפורניה, שבה נרצח צעיר ליד הבמה.''',
'''האלבום נפתח ב־Gimme Shelter, אחד השירים המאיימים ביותר ברוק: גיטרה רועדת, מפוחית, והזמרת מרי קלייטון, שהוזמנה לאולפן באמצע הלילה, שרה "Rape, murder, it’s just a shot away" בקול שנסדק מעוצמה. Love in Vain הוא בלוז של רוברט ג׳ונסון, Country Honk הוא גרסה כפרית ללהיט Honky Tonk Women, ו־Midnight Rambler הוא בלוז ארוך ומפחיד על רוצח. והאלבום נגמר ב־You Can’t Always Get What You Want, עם מקהלה גדולה מלונדון, שיר עם מסר צנוע: לא תמיד מקבלים את מה שרוצים, אבל אם מנסים, אולי מקבלים את מה שצריך.''',
'''Let It Bleed הוא האלבום השני ברצף של ארבעה שרבים רואים כשיא של הסטונס, אחרי Beggars Banquet (אלבום 107). רבים רואים בו את הסיום האפל של שנות השישים: במקום אהבה ושלום, מלחמה, פחד ואלימות. Gimme Shelter נחשב לאחד השירים הגדולים שלהם, ומופיע עד היום בסרטים על אותה תקופה.''',
'''שמעו את Gimme Shelter והקשיבו לרגע שבו הקול של מרי קלייטון נסדק. ואחר כך את You Can’t Always Get What You Want עד הסוף, ושימו לב איך מקהלה של כנסייה הופכת לשיר רוק.''',
], [
('Gimme Shelter', 'שיר מאיים על מלחמה ופחד, עם הקול המצמרר של מרי קלייטון.'),
('You Can’t Always Get What You Want', 'הסיום: מקהלה, קרן יער ושיר עם מסר צנוע וחכם.'),
('Midnight Rambler', 'בלוז ארוך ומפחיד על רוצח, שמאיץ ומאט.'),
])

add(149, [
'''ניק דרייק היה סטודנט צעיר ושקט באוניברסיטת קיימברידג׳, שכתב שירים וניגן בגיטרה בכוונונים מיוחדים שהמציא. המפיק ג׳ו בויד, שהפיק גם את The Incredible String Band (אלבום 109), שמע אותו בהופעה קטנה בלונדון והחתים אותו מיד. Five Leaves Left הוקלט במשך כשנה, ויצא ביולי 1969, כשדרייק היה בן 21. שמו לקוח מהאזהרה שהופיעה בחבילות נייר סיגריות, כשנשארו רק חמישה ניירות.''',
'''זה אלבום שקט, עדין ועצוב: גיטרה אקוסטית עם אצבעות שנעות בדיוק מופלא, קול רך, כמעט לוחש, ומילים על בדידות, על זמן ועל טבע. סביבו מנגנים הבסיסט דני תומפסון מ־Pentangle (אלבום 147) ואחרים, וחברו מקיימברידג׳ רוברט קירבי כתב לו עיבודי כלי קשת יפהפיים. River Man, עם כלי קשת שמתנדנדים כמו נהר איטי, הוא אולי השיר המפורסם שלו. Way to Blue הוא שיר קטן לקול וכלי קשת בלבד, ו־Cello Song נשען על צ׳לו שרץ מתחת לגיטרה.''',
'''בזמנו האלבום כמעט לא נמכר, ודרייק, שהיה ביישן מאוד ושנא להופיע, לא קידם אותו. הוא הקליט עוד שני אלבומים, שקיבלו גם הם מעט תשומת לב, ומת ב־1974, בגיל 26, ממנת יתר של תרופות נגד דיכאון. רק עשרות שנים אחר כך, בעיקר בסוף שנות התשעים, העולם גילה אותו, והיום הוא נחשב לאחד מכותבי השירים הגדולים של בריטניה. אלבומיו נמכרים היום הרבה יותר מאשר בחייו.''',
'''הקשיבו בשקט, לבד, ורצוי בערב של סתיו. ושימו לב ל־River Man: הוא בנוי על קצב של חמש פעימות, כמעט בלי שמרגישים.''',
], [
('River Man', 'שיר על נהר ועל אדם שמחכה, עם כלי קשת שמתנדנדים כמו מים.'),
('Way to Blue', 'שיר קטן ויפה לקול וכלי קשת בלבד, בלי גיטרה.'),
('Cello Song', 'צ׳לו שרץ מתחת לגיטרה, ושיר על חלום ובריחה.'),
])

add(150, [
'''בסוף שנות השישים דאסטי ספרינגפילד (אלבום 45) הייתה כוכבת גדולה בבריטניה, אבל הרגישה שהקריירה שלה נתקעה. היא חתמה בחברת Atlantic האמריקאית, הבית של ארית׳ה פרנקלין (אלבומים 106 ו־117), והמפיקים ג׳רי וקסלר, טום דאוד ואריף מארדין לקחו אותה לממפיס, לאולפן American Sound, עם נגני האולפן הטובים של העיר. דאסטי, שהעריצה את זמרות הסול השחורות, נבהלה: וקסלר, לפי דבריה, דיבר רק על ארית׳ה. בסוף היא הקליטה את השירה שלה מאוחר יותר, בניו יורק. Dusty in Memphis יצא בתחילת 1969.''',
'''הלהקה של ממפיס מנגנת רך, עמוק ומדויק, בלי להגזים: גיטרה עדינה, עוגב, בס חם, וכלי קשת וכלי נשיפה שנוספו אחר כך. מעל הכול הקול של דאסטי, נמוך, חושני ושביר, שלוחש יותר משהוא צועק. השירים נכתבו בידי הכותבים הגדולים של התקופה: קרול קינג וג׳רי גופין, רנדי ניומן, ברט בכרך והאל דייוויד, ומישל לגראן. Son of a Preacher Man, שנכתב במקור בשביל ארית׳ה, שסירבה לו, הוא שיר על אהבה ראשונה עם בנו של כומר. The Windmills of Your Mind מתוך סרט, מסתחרר כמו טחנת רוח.''',
'''Son of a Preacher Man הפך ללהיט באמריקה ובבריטניה, וכשארית׳ה שמעה אותו היא הקליטה אותו בעצמה. אבל האלבום עצמו נמכר מעט מאוד. רק עם השנים הוא הפך לאחד מאלבומי הסול־פופ האהובים ביותר, ובשנות התשעים, כשהשיר הופיע בסרט "ספרות זולה", דור חדש גילה אותו. זה אחד המקרים הנדירים שבהם זמרת לבנה מבריטניה נכנסה לעולם של הסול האמריקאי ונשמעה שייכת לגמרי.''',
'''שמעו את Son of a Preacher Man, ואחר כך את A Girl Called Dusty באלבום 45, חמש שנים קודם: אותה זמרת, והפעם כמעט בלחישה. ואז שמעו את ארית׳ה באלבום 117, ותבינו ממי דאסטי פחדה, ובצדק.''',
], [
('Son of a Preacher Man', 'שיר על אהבה ראשונה עם בנו של כומר, בקול חושני ושקט.'),
('Just a Little Lovin’', 'הפתיחה: שיר רך ואיטי על כך שקצת אהבה בבוקר משנה את היום.'),
('The Windmills of Your Mind', 'שיר מסתחרר מתוך סרט, עם כלי קשת שמסתובבים כמו טחנת רוח.'),
])
